export const WARMTEPOMP_DASHBOARD_HTML: string = "<title>Warmtepomp SPRSUN</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&family=Outfit:wght@300;400;700&display=swap\">\n<style>\n/* Layout: alleen de popup van de warmtepomp (wandtablet). Links het installatieschema met de kast\n   (ventilator links over de volle hoogte, onderdelen rechts), de leidingen naar het boilervat en een\n   plat gelegde vloerverwarming. Rechts tabbladen met overzicht, instellingen, tijdschema en waarden.\n   Bewust één donker thema, passend bij het huisdashboard. */\n:root{\n  color-scheme:dark;\n  --backdrop:#07080c;\n  --panel:#12151c; --panel-2:#181c26; --panel-3:#20252f; --line:#272c38; --line-2:#323949;\n  --fg:#e9ebf1; --muted:#8a92a3; --dim:#5d6575;\n  --accent:#ff8d4d; --accent-soft:rgba(255,141,77,.16); --accent-ink:#1d0f06;\n  --ok:#4ade80; --warn:#fbbf24; --cold:#60a5fa; --hot:#f87171; --ice:#7dd3fc;\n  --f-display:\"Outfit\",\"Figtree\",system-ui,sans-serif;\n  --f-ui:\"Figtree\",system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;\n  --r:14px;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml,body{height:100%}\nbody{background:#0e1117;margin:0;padding:0;color:var(--fg);font-family:var(--f-ui);font-size:14px;overflow:hidden;-webkit-tap-highlight-color:transparent;touch-action:manipulation;-webkit-user-select:none;user-select:none}\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer;touch-action:manipulation}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.i{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}\n.num{font-variant-numeric:tabular-nums}\n.hit{cursor:pointer}\n.chip{display:inline-flex;align-items:center;gap:8px;min-height:40px;padding:0 14px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);font-size:13px;font-weight:500}\n.chip .dot{width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}\n.badge{font-size:10.5px;font-weight:600;padding:3px 7px;border-radius:6px;background:var(--panel-3);color:var(--muted);white-space:nowrap}\n.badge.heat{background:rgba(251,146,60,.16);color:#fdba74}\n.badge.dhw{background:rgba(251,191,36,.15);color:#fcd34d}\n.badge.cool{background:rgba(96,165,250,.16);color:#93c5fd}\n.badge.defrost{background:rgba(125,211,252,.16);color:#bae6fd}\n.badge.off{background:rgba(248,113,113,.16);color:#fca5a5}\n.reopen{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);min-height:56px;padding:0 22px;border-radius:14px;background:var(--accent);color:var(--accent-ink);font-weight:700;display:inline-flex;gap:10px;align-items:center}\n\n/* ---------- popup ---------- */\n.modal{position:fixed;left:0;top:0;width:100%;height:100%;transform:none;border-radius:20px;display:grid;grid-template-rows:auto minmax(0,1fr);background:var(--panel);border:1px solid var(--line-2);border-radius:22px;box-shadow:0 40px 100px rgba(0,0,0,.6);overflow:hidden}\n.m-head{display:flex;align-items:center;gap:14px;padding:14px 16px 14px 20px;border-bottom:1px solid var(--line);flex-wrap:wrap}\n.m-title{display:flex;align-items:center;gap:12px;min-width:0;flex:1}\n.m-title .ico{width:44px;height:44px;border-radius:12px;background:var(--accent-soft);color:var(--accent)}\n.m-title h2{margin:0;font-family:var(--f-display);font-weight:400;font-size:24px;line-height:1.1}\n.m-title p{margin:2px 0 0;color:var(--muted);font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.m-title .badge{font-size:12px;padding:5px 9px}\n.m-actions{display:flex;gap:8px;align-items:center;position:relative}\n.icon-btn{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;background:var(--panel-2);border:1px solid var(--line)}\n.power-btn{display:inline-flex;align-items:center;gap:8px;height:48px;padding:0 16px 0 12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);font-weight:600}\n.power-btn .i{width:22px;height:22px;stroke-width:2.2}\n.power-btn[aria-checked=\"true\"]{background:rgba(74,222,128,.12);border-color:rgba(74,222,128,.45);color:#bbf7d0}\n.power-btn[aria-checked=\"true\"] .i{color:var(--ok)}\n.power-btn[aria-checked=\"false\"] .i{color:var(--hot)}\n.sim{min-height:48px}\n.confirm{position:absolute;right:56px;top:56px;z-index:5;width:320px;display:grid;gap:12px;padding:14px;border-radius:14px;background:#1d222c;border:1px solid rgba(248,113,113,.45);box-shadow:0 20px 50px rgba(0,0,0,.5)}\n.confirm div{display:flex;gap:8px;justify-content:flex-end}\n.sim-menu{position:absolute;top:56px;right:0;z-index:6;min-width:270px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:6px;box-shadow:0 20px 50px rgba(0,0,0,.5)}\n.sim-menu button{display:flex;width:100%;min-height:46px;padding:6px 12px;border-radius:10px;text-align:left;line-height:1.3}\n.sim-menu button:hover{background:var(--panel-2)}\n.sim-menu button[aria-checked=\"true\"]{background:var(--accent-soft);color:#ffd2b8}\n.sim-menu small{color:var(--muted);font-size:11.5px}\n.sim-menu .sep{height:1px;background:var(--line);margin:6px 4px}\n.btn{min-height:44px;padding:0 16px;border-radius:11px;background:var(--panel-3);border:1px solid var(--line);font-weight:600}\n.btn.danger{background:rgba(248,113,113,.18);border-color:rgba(248,113,113,.45);color:#fecaca}\n\n.m-body{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(380px,1fr);min-height:0}\n.m-schema{display:grid;grid-template-rows:minmax(0,1fr) auto;min-height:0;background:radial-gradient(120% 90% at 30% 20%,#161b25 0%,#0e1117 70%);border-right:1px solid var(--line)}\n.m-schema svg{width:100%;height:100%;display:block;min-height:0}\n.lamps{display:flex;flex-wrap:wrap;gap:8px;padding:12px 16px 14px;border-top:1px solid var(--line);align-items:center}\n#lampRow{display:contents}\n.lamp{display:inline-flex;align-items:center;gap:8px;min-height:36px;padding:0 12px;border-radius:10px;background:var(--panel-2);border:1px solid var(--line);font-size:12.5px;color:var(--muted)}\n.lamp i{width:9px;height:9px;border-radius:50%;background:var(--dim)}\n.lamp.on{color:var(--fg)}\n.lamp.on i{background:var(--ok);box-shadow:0 0 0 4px rgba(74,222,128,.15)}\n.lamp.on.ice i{background:var(--ice);box-shadow:0 0 0 4px rgba(125,211,252,.18)}\n.lamp.status{margin-left:auto;color:var(--fg);background:transparent;border-color:transparent;padding-right:0}\n\n.m-side{display:grid;grid-template-rows:auto minmax(0,1fr);min-height:0}\n.tabs{display:flex;gap:6px;overflow-x:auto;padding:12px 16px;scrollbar-width:none;border-bottom:1px solid var(--line)}\n.tabs::-webkit-scrollbar{display:none}\n.tab{display:inline-flex;align-items:center;gap:7px;min-height:44px;padding:0 14px;border-radius:11px;white-space:nowrap;color:var(--muted);font-weight:500;background:var(--panel-2);border:1px solid transparent}\n.tab[aria-selected=\"true\"]{color:var(--fg);border-color:rgba(255,141,77,.45);background:var(--accent-soft)}\n.m-panel{overflow-y:auto;overscroll-behavior:contain;padding:16px 16px 28px}\n.panel{display:grid;gap:20px}\n.sec{display:grid;gap:10px}\n.sec-h{font-size:11.5px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:8px}\n.sec-h em{font-style:normal;text-transform:none;letter-spacing:0;font-weight:400;color:var(--dim);margin-left:auto}\n.box{background:var(--panel-2);border:1px solid var(--line);border-radius:var(--r)}\n.row{display:grid;gap:10px;padding:14px 16px}\n.row + .row{border-top:1px solid var(--line)}\n.row-line{display:flex;align-items:center;gap:12px;min-width:0}\n.ico{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--panel-3);color:#c8ced9;flex:none}\n.row-text{flex:1;min-width:0}\n.row-title{font-weight:600;font-size:15px}\n.row-sub{color:var(--muted);font-size:12px;margin-top:2px}\n\n.statusbox{padding:16px;display:grid;gap:4px}\n.statusbox b{font-size:17px;font-weight:600}\n.statusbox span{color:var(--muted);font-size:12.5px}\n.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.tile{padding:12px;border-radius:12px;background:var(--panel-2);border:1px solid var(--line);display:grid;gap:4px;min-width:0;text-align:left}\n.tile span{font-size:11.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tile b{font-size:20px;font-weight:500;white-space:nowrap}\n.tile b small{font-size:11.5px;color:var(--muted);font-weight:400;margin-left:2px}\n.tile em{font-style:normal;font-size:11px;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tile .sw{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}\n\n.seg{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}\n.seg button{min-height:52px;padding:8px 12px;border-radius:12px;background:var(--panel-3);border:1px solid var(--line);text-align:left;display:flex;align-items:center;gap:10px;font-weight:500;font-size:13.5px;line-height:1.2}\n.seg button .i{color:var(--muted)}\n.seg button[aria-pressed=\"true\"]{background:var(--accent-soft);border-color:rgba(255,141,77,.6);color:#ffe1cf}\n.seg button[aria-pressed=\"true\"] .i{color:var(--accent)}\n.seg.compact button{min-height:46px;justify-content:center;text-align:center}\n.confirmed{font-size:12.5px;color:var(--muted);display:flex;gap:8px;align-items:center}\n.confirmed b{color:var(--fg);font-weight:600}\n.confirmed .dot{width:7px;height:7px;border-radius:50%;background:var(--ok)}\n.step-ctrl{display:flex;align-items:center;gap:6px;flex:none}\n.step{width:48px;height:48px;border-radius:12px;background:var(--panel-3);border:1px solid var(--line);font-size:24px;line-height:1;font-weight:300;display:grid;place-items:center}\n.step:active{background:var(--accent-soft);border-color:rgba(255,141,77,.5)}\n.step-val{min-width:80px;text-align:center;font-size:22px;font-weight:500}\n.step-val small{font-size:12px;color:var(--muted);margin-left:2px;font-weight:400}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:30px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:6px;border-radius:3px;background:linear-gradient(90deg,var(--trk,var(--accent)) var(--p,50%),var(--panel-3) var(--p,50%))}\ninput[type=range]::-moz-range-track{height:6px;border-radius:3px;background:linear-gradient(90deg,var(--trk,var(--accent)) var(--p,50%),var(--panel-3) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:26px;height:26px;border-radius:50%;background:#f4f5f8;border:4px solid var(--trk,var(--accent));margin-top:-10px;box-shadow:0 2px 8px rgba(0,0,0,.4)}\ninput[type=range]::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#f4f5f8;border:4px solid var(--trk,var(--accent))}\n.range-ends{display:flex;justify-content:space-between;font-size:11px;color:var(--dim);margin-top:-6px}\n.switch{width:60px;height:36px;border-radius:18px;background:var(--panel-3);border:1px solid var(--line);position:relative;flex:none;transition:background .2s}\n.switch::after{content:\"\";position:absolute;top:4px;left:4px;width:26px;height:26px;border-radius:50%;background:#9aa2b2;transition:transform .22s,background .22s}\n.switch[aria-checked=\"true\"]{background:rgba(255,141,77,.35);border-color:rgba(255,141,77,.6)}\n.switch[aria-checked=\"true\"]::after{transform:translateX(24px);background:#fff}\n\n.list .li{display:flex;align-items:center;gap:12px;padding:11px 16px;min-height:48px}\n.list .li + .li{border-top:1px solid var(--line)}\n.li .sw{width:9px;height:9px;border-radius:3px;flex:none;background:var(--dim)}\n.li .lt{flex:1;min-width:0}\n.li .lt small{display:block;color:var(--dim);font-size:11px}\n.li b{font-weight:600;white-space:nowrap}\n\n.chart-wrap{padding:12px 10px 8px}\n.chart-wrap svg{width:100%;height:auto;display:block}\n.chart-wrap text{font:11px var(--f-ui);fill:var(--muted)}\n.legend{display:flex;flex-wrap:wrap;gap:6px;padding:4px 6px}\n.legend button{display:inline-flex;align-items:center;gap:7px;min-height:36px;padding:0 11px;border-radius:9px;background:var(--panel-3);border:1px solid var(--line);font-size:12.5px}\n.legend button i{width:10px;height:10px;border-radius:50%}\n.legend button[aria-pressed=\"false\"]{opacity:.45}\n\n.week{padding:14px 12px 12px;display:grid;gap:6px}\n.week-hours,.week-row{display:grid;grid-template-columns:30px minmax(0,1fr);align-items:center;gap:8px}\n.week-hours div{display:flex;justify-content:space-between;font-size:10.5px;color:var(--dim)}\n.week-row > b{font-size:12.5px;font-weight:600;color:#c9cfda}\n.cells{display:grid;grid-template-columns:repeat(24,minmax(0,1fr));gap:2px;touch-action:none}\n.cells span{height:34px;border-radius:4px;background:var(--panel-3)}\n.cells span.on{background:linear-gradient(180deg,#ffa36e,#f07b3c)}\n.week-foot{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;padding-top:6px}\n.key{display:flex;gap:14px;font-size:12px;color:var(--muted)}\n.key i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px;vertical-align:-1px}\n\n/* tekst en kast in het schema */\n.tag-l{font:500 12px var(--f-ui);fill:#8a92a3;letter-spacing:.02em}\n.tag-v{font:600 16px var(--f-ui);fill:#f1f3f7}\n.cap{font:700 10.5px var(--f-ui);fill:#6b7385;letter-spacing:.14em}\n.big-t{font:700 30px var(--f-ui);fill:#fff}\n#schema .hit:hover > rect:first-child{stroke:#4a5366}\n#schema .front{transition:opacity .5s;cursor:pointer}\n#schema{background:linear-gradient(180deg,#0b1020,#1a2542 55%,#141a24 85%)}\n#schema .bub circle{transform-box:fill-box;animation:rise 4.5s ease-in infinite}\n#schema .wave path{animation:waft 3.2s ease-out infinite}\n#warmG{transition:transform 1.8s cubic-bezier(.4,0,.2,1)}\n#waveG{animation:wv 2.6s linear infinite}\n@keyframes wv{to{transform:translateX(-40px)}}\n.think{padding:14px 16px;display:grid;gap:12px}\n.th-top{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.th-more{font-size:12.5px;font-weight:600;color:var(--accent);min-height:36px;padding:0 10px;border-radius:9px;background:var(--accent-soft)}\n.th-sub{color:var(--muted);font-size:13px;margin-top:-6px}\n.th-steps{display:grid;gap:12px;padding-top:6px;border-top:1px solid var(--line)}\n.th-sum{font-weight:600;font-size:21px;line-height:1.25}\n.th-step{display:flex;gap:12px;align-items:flex-start}\n.th-step i{flex:none;width:26px;height:26px;border-radius:50%;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;font-style:normal;font-weight:700;font-size:13px}\n.th-step b{display:block;font-size:13px;margin-bottom:2px}\n.th-step span{color:var(--muted);font-size:12.5px;line-height:1.45}\n.row.dim{opacity:.45;pointer-events:none}\n#fc svg{width:100%;height:auto;display:block}\n#fc svg text{fill:#8a92a3;font:500 10px var(--f-ui)}\n.batt{padding:16px;display:grid;gap:12px}\n.batt-top{display:flex;align-items:center;justify-content:space-between}\n.batt-top b{font-size:34px;font-weight:500}\n.batt-top small{font-size:15px;color:var(--muted);margin-left:2px}\n.chip-s{font-size:12px;font-weight:600;padding:5px 10px;border-radius:8px;background:var(--panel-3);color:var(--muted)}\n.chip-s.on{background:rgba(74,222,128,.15);color:#86efac}\n.batt-bar{height:12px;border-radius:6px;background:var(--panel-3);overflow:hidden}\n.batt-bar i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#60a5fa,#4ade80)}\n.batt-sub{display:flex;justify-content:space-between;font-size:12.5px;color:var(--muted)}\n@keyframes rise{0%{transform:translateY(0);opacity:0}15%{opacity:.85}100%{transform:translateY(-260px);opacity:0}}\n@keyframes waft{0%{transform:translateY(0);opacity:0}25%{opacity:.7}100%{transform:translateY(-34px);opacity:0}}\n@media (prefers-reduced-motion:reduce){#schema .bub,#schema .wave{display:none}}\n#schema .inner{opacity:0;pointer-events:none;transition:opacity .5s}\n#schema.open .front{opacity:0;pointer-events:none}\n#schema.open .inner{opacity:1;pointer-events:auto}\n\n.toast{position:fixed;left:50%;bottom:calc(40px + env(safe-area-inset-bottom,0px));transform:translate(-50%,20px);opacity:0;z-index:40;background:#1d222c;border:1px solid #333a49;border-radius:12px;padding:12px 16px;font-size:13.5px;display:flex;gap:10px;align-items:center;transition:.25s;pointer-events:none;max-width:calc(100% - 32px)}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.toast .i{color:var(--ok)}\n\n@media (max-width:1500px){\n  .tab .i{display:none}\n  .tab{padding:0 12px}\n}\n@media (max-width:1100px){\n  .m-body{grid-template-columns:minmax(0,1.25fr) minmax(330px,1fr)}\n  .tiles{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n@media (max-width:860px){\n  body{overflow:auto}\n  .modal{position:relative;left:0;top:0;transform:none;width:100%;height:auto;min-height:100%;border-radius:0;border:0}\n  .m-body{grid-template-columns:1fr}\n  .m-schema{border-right:0;border-bottom:1px solid var(--line)}\n  .m-schema svg{height:auto;aspect-ratio:1160/560}\n  .m-side{grid-template-rows:auto auto}\n  .m-panel{overflow:visible}\n  .m-title{flex-basis:100%}\n  .m-actions{margin-left:auto}\n  .row-line{flex-wrap:wrap}\n  .step-ctrl{margin-left:auto}\n  .m-head{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n  .confirm{right:0;width:min(320px,calc(100vw - 32px))}\n  .sim span:last-child{display:none}\n}\n</style>\n\n<div class=\"modal\" id=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"mTitle\">\n  <header class=\"m-head\">\n    <div class=\"m-title\">\n      <span class=\"ico\"><svg class=\"i\" viewBox=\"0 0 24 24\" style=\"width:24px;height:24px\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"10\" cy=\"12\" r=\"4\"/><path d=\"M17 8v8\"/></svg></span>\n      <div style=\"min-width:0\"><h2 id=\"mTitle\">Warmtepomp</h2><p id=\"mSub\">SPRSUN warmtepomp · Carel-regelaar</p></div>\n      <b class=\"badge\" id=\"mBadge\">Stand-by</b>\n    </div>\n    <div class=\"m-actions\">\n      <button class=\"icon-btn\" id=\"mClose\" aria-label=\"Sluiten\"><svg class=\"i\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n    </div>\n  </header>\n  <div class=\"m-body\">\n    <section class=\"m-schema\">\n      <svg id=\"schema\" viewBox=\"170 90 990 560\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Installatieschema warmtepomp, buffervat en vloerverwarming\">\n        <defs>\n          <linearGradient id=\"tankShine\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#000\" stop-opacity=\".35\"/><stop offset=\".22\" stop-color=\"#fff\" stop-opacity=\".22\"/><stop offset=\".45\" stop-color=\"#fff\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#000\" stop-opacity=\".4\"/></linearGradient>\n          <linearGradient id=\"coldGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3b82f6\"/><stop offset=\"1\" stop-color=\"#1e3a8a\"/></linearGradient>\n          <linearGradient id=\"warmGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop id=\"tankTop\" offset=\"0\" stop-color=\"#ef4444\"/><stop id=\"tankBot\" offset=\"1\" stop-color=\"#b91c1c\"/></linearGradient>\n          <linearGradient id=\"floorGlowGrad\" x1=\"0\" y1=\"1\" x2=\"0\" y2=\"0\"><stop id=\"floorGlowStop\" offset=\"0\" stop-color=\"#fb923c\" stop-opacity=\".34\"/><stop offset=\"1\" stop-color=\"#fb923c\" stop-opacity=\"0\"/></linearGradient>\n          <linearGradient id=\"roomGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#1b2235\"/><stop offset=\"1\" stop-color=\"#2a2f44\"/></linearGradient>\n          <linearGradient id=\"glassGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#0f1730\"/><stop offset=\"1\" stop-color=\"#27345c\"/></linearGradient>\n          <linearGradient id=\"casing\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#eef1f5\"/><stop offset=\"1\" stop-color=\"#d5dae2\"/></linearGradient>\n          <pattern id=\"fins\" width=\"6\" height=\"26\" patternUnits=\"userSpaceOnUse\"><rect width=\"6\" height=\"26\" fill=\"#1b2a38\"/><path d=\"M3 0V26\" stroke=\"#3d6a8c\" stroke-width=\"1.4\"/></pattern>\n          <pattern id=\"screed\" width=\"14\" height=\"14\" patternUnits=\"userSpaceOnUse\"><rect width=\"14\" height=\"14\" fill=\"#25211f\"/><circle cx=\"4\" cy=\"4\" r=\".9\" fill=\"#34302d\"/><circle cx=\"10\" cy=\"11\" r=\".8\" fill=\"#34302d\"/></pattern>\n          <pattern id=\"plates\" width=\"50\" height=\"8\" patternUnits=\"userSpaceOnUse\"><rect width=\"50\" height=\"8\" fill=\"#2a303b\"/><path d=\"M0 4H50\" stroke=\"#46505f\" stroke-width=\"2\"/></pattern>\n          <pattern id=\"bricks\" width=\"22\" height=\"11\" patternUnits=\"userSpaceOnUse\"><rect width=\"22\" height=\"11\" fill=\"#4a2a24\"/><path d=\"M0 .5H22M0 5.5H22M11 .5V5.5M.5 5.5V11M21.5 5.5V11\" stroke=\"#37201b\" stroke-width=\"1\"/></pattern>\n          <clipPath id=\"tankClip\"><rect x=\"870\" y=\"270\" width=\"80\" height=\"278\" rx=\"24\"/></clipPath>\n          <mask id=\"grilleHole\" maskUnits=\"userSpaceOnUse\" x=\"0\" y=\"200\" width=\"800\" height=\"360\"><rect x=\"0\" y=\"200\" width=\"800\" height=\"360\" fill=\"#fff\"/><circle cx=\"174\" cy=\"380\" r=\"128\" fill=\"#000\"/></mask>\n        </defs>\n\n        <!-- lucht -->\n        <g fill=\"#fff\"><circle cx=\"60\" cy=\"130\" r=\"1.6\" opacity=\".7\"/><circle cx=\"170\" cy=\"180\" r=\"1.2\" opacity=\".5\"/><circle cx=\"300\" cy=\"120\" r=\"1.8\" opacity=\".8\"/><circle cx=\"430\" cy=\"170\" r=\"1.2\" opacity=\".5\"/><circle cx=\"560\" cy=\"130\" r=\"1.5\" opacity=\".7\"/><circle cx=\"660\" cy=\"190\" r=\"1.2\" opacity=\".5\"/><circle cx=\"760\" cy=\"110\" r=\"1.4\" opacity=\".6\"/><circle cx=\"1130\" cy=\"120\" r=\"1.2\" opacity=\".5\"/></g>\n        <circle cx=\"610\" cy=\"120\" r=\"18\" fill=\"#f3efd8\" opacity=\".92\"/><circle cx=\"618\" cy=\"115\" r=\"16\" fill=\"#0f1730\" opacity=\".55\"/>\n\n        <!-- buiten: tegelvloer en struikjes -->\n        <ellipse cx=\"712\" cy=\"552\" rx=\"34\" ry=\"22\" fill=\"#1f4d3a\"/><ellipse cx=\"692\" cy=\"556\" rx=\"24\" ry=\"16\" fill=\"#27614a\"/><ellipse cx=\"722\" cy=\"544\" rx=\"18\" ry=\"12\" fill=\"#2f7458\" opacity=\".9\"/>\n        <rect x=\"0\" y=\"560\" width=\"740\" height=\"100\" fill=\"#141a24\"/><path d=\"M0 590H740M0 622H740M120 560V660M260 560V660M400 560V660M540 560V660M680 560V660\" stroke=\"#1d2431\" stroke-width=\"2\"/>\n        <rect x=\"0\" y=\"548\" width=\"740\" height=\"12\" fill=\"#2b3039\"/>\n        <ellipse cx=\"381\" cy=\"551\" rx=\"200\" ry=\"7\" fill=\"#000\" opacity=\".4\"/>\n\n        <!-- huis: doorsnede van de woonkamer met vloer -->\n        <rect x=\"740\" y=\"150\" width=\"14\" height=\"510\" fill=\"url(#bricks)\"/>\n        <rect id=\"floorGlow\" x=\"760\" y=\"400\" width=\"390\" height=\"148\" fill=\"url(#floorGlowGrad)\" opacity=\"0\" style=\"transition:opacity 1s\"/>\n        <rect x=\"754\" y=\"548\" width=\"406\" height=\"8\" fill=\"#6b4a32\"/>\n        <rect x=\"754\" y=\"556\" width=\"406\" height=\"50\" fill=\"url(#screed)\"/>\n        <rect x=\"754\" y=\"606\" width=\"406\" height=\"20\" fill=\"#26332a\"/>\n        <rect x=\"754\" y=\"626\" width=\"406\" height=\"34\" fill=\"#2f3138\"/>\n        <text x=\"973\" y=\"646\" text-anchor=\"middle\" class=\"cap\">VLOERVERWARMING</text>\n        <rect x=\"736\" y=\"381\" width=\"22\" height=\"22\" rx=\"4\" fill=\"#3a404c\" stroke=\"#6b7485\" stroke-width=\"1.5\"/>\n        <rect x=\"736\" y=\"405\" width=\"22\" height=\"22\" rx=\"4\" fill=\"#3a404c\" stroke=\"#6b7485\" stroke-width=\"1.5\"/>\n        <rect x=\"868\" y=\"538\" width=\"84\" height=\"10\" rx=\"3\" fill=\"#3a404c\"/>\n\n        <!-- buitenunit (verkleind, zodat hij in verhouding staat met vat en huis) -->\n        <g id=\"unit\" transform=\"translate(185 247) scale(.55)\">\n          <rect x=\"64\" y=\"536\" width=\"38\" height=\"12\" rx=\"2\" fill=\"#5d6575\"/><rect x=\"610\" y=\"536\" width=\"38\" height=\"12\" rx=\"2\" fill=\"#5d6575\"/>\n          <g class=\"inner\">\n            <rect x=\"12\" y=\"224\" width=\"688\" height=\"312\" rx=\"18\" fill=\"#141922\" stroke=\"#2b3242\" stroke-width=\"1.5\"/>\n            <rect x=\"24\" y=\"236\" width=\"300\" height=\"288\" rx=\"10\" fill=\"url(#fins)\" stroke=\"#2f4a61\"/>\n            <rect id=\"frostFins\" x=\"24\" y=\"236\" width=\"300\" height=\"288\" rx=\"10\" fill=\"#e0f2fe\" opacity=\"0\" style=\"transition:opacity .8s\"/>\n          </g>\n          <g class=\"hit\" id=\"fanGroup\" transform=\"translate(174 380)\">\n            <circle r=\"142\" fill=\"#0f1319\" stroke=\"#2b3242\"/>\n            <g id=\"fanRot\" fill=\"#4d5664\"><path d=\"M0 -8 C 16 -16 28 -40 10 -50 C -4 -37 -8 -21 0 -8Z\" transform=\"scale(2.4)\"/><path d=\"M0 -8 C 16 -16 28 -40 10 -50 C -4 -37 -8 -21 0 -8Z\" transform=\"rotate(72) scale(2.4)\"/><path d=\"M0 -8 C 16 -16 28 -40 10 -50 C -4 -37 -8 -21 0 -8Z\" transform=\"rotate(144) scale(2.4)\"/><path d=\"M0 -8 C 16 -16 28 -40 10 -50 C -4 -37 -8 -21 0 -8Z\" transform=\"rotate(216) scale(2.4)\"/><path d=\"M0 -8 C 16 -16 28 -40 10 -50 C -4 -37 -8 -21 0 -8Z\" transform=\"rotate(288) scale(2.4)\"/></g>\n            <circle r=\"16\" fill=\"#7b838f\"/><circle r=\"6\" fill=\"#4d5664\"/>\n            <circle id=\"frostFan\" r=\"142\" fill=\"#e0f2fe\" opacity=\"0\" style=\"transition:opacity .8s\"/>\n          </g>\n          <g class=\"inner\">\n            <g id=\"refPipes\"></g>\n            <rect x=\"584\" y=\"240\" width=\"80\" height=\"90\" rx=\"6\" fill=\"url(#plates)\" stroke=\"#46505f\"/>\n            <circle cx=\"664\" cy=\"264\" r=\"5\" fill=\"#8b939f\"/><circle cx=\"664\" cy=\"306\" r=\"5\" fill=\"#8b939f\"/>\n            <g class=\"hit\" data-tab=\"waarden\">\n              <rect x=\"584\" y=\"432\" width=\"80\" height=\"80\" rx=\"36\" fill=\"#2a303b\" stroke=\"#566070\" stroke-width=\"2\"/>\n              <circle cx=\"624\" cy=\"472\" r=\"22\" fill=\"#1b2029\" stroke=\"#46505f\" stroke-width=\"2\"/>\n              <circle id=\"compLed\" cx=\"624\" cy=\"472\" r=\"9\" fill=\"#5d6575\"/>\n            </g>\n            <g transform=\"translate(500 380)\"><path d=\"M-12 -13 L12 -13 L-12 13 L12 13Z\" fill=\"#2a303b\" stroke=\"#8b939f\" stroke-width=\"1.6\"/><path d=\"M0 0 V-18 M-7 -18 H7\" stroke=\"#8b939f\" stroke-width=\"1.6\"/></g>\n            <circle cx=\"700\" cy=\"264\" r=\"9\" fill=\"#7d8694\" stroke=\"#5d6575\" stroke-width=\"2\"/><circle cx=\"700\" cy=\"306\" r=\"9\" fill=\"#7d8694\" stroke=\"#5d6575\" stroke-width=\"2\"/>\n          </g>\n          <g id=\"hpFront\" class=\"front\">\n            <rect x=\"12\" y=\"224\" width=\"688\" height=\"312\" rx=\"18\" fill=\"url(#casing)\" stroke=\"#9aa3b0\" stroke-width=\"2\" mask=\"url(#grilleHole)\"/>\n            <circle cx=\"174\" cy=\"380\" r=\"131\" fill=\"none\" stroke=\"#aab2bd\" stroke-width=\"6\"/>\n            <g fill=\"none\" stroke=\"#b3bbc6\" stroke-width=\"2.4\"><circle cx=\"174\" cy=\"380\" r=\"100\"/><circle cx=\"174\" cy=\"380\" r=\"72\"/><circle cx=\"174\" cy=\"380\" r=\"42\"/><path d=\"M174 252V508M46 380H302M83.5 289.5L264.5 470.5M264.5 289.5L83.5 470.5\"/></g>\n            <circle cx=\"174\" cy=\"380\" r=\"24\" fill=\"#c4cad3\" stroke=\"#aab2bd\" stroke-width=\"2\"/>\n            <text x=\"512\" y=\"392\" text-anchor=\"middle\" font-family=\"Outfit, Figtree, sans-serif\" font-style=\"italic\" font-weight=\"700\" font-size=\"50\" letter-spacing=\"2\" fill=\"#5d6675\">SPRSUN</text>\n            <circle cx=\"700\" cy=\"264\" r=\"9\" fill=\"#7d8694\" stroke=\"#5d6575\" stroke-width=\"2\"/><circle cx=\"700\" cy=\"306\" r=\"9\" fill=\"#7d8694\" stroke=\"#5d6575\" stroke-width=\"2\"/>\n          </g>\n        </g>\n\n        <!-- meetpunten: genummerde speldjes op de unit + overzicht erboven (alleen bij geopende kast) -->\n        <g class=\"inner\" id=\"pins\"></g>\n        <g class=\"inner hit\" id=\"refPanel\" data-tab=\"waarden\" transform=\"translate(192 166)\"></g>\n\n        <!-- watercircuit (JS) -->\n        <g id=\"waterPipes\"></g>\n\n        <!-- kaartjes onder de unit -->\n        <g class=\"hit\" data-tab=\"overzicht\">\n          <rect x=\"192\" y=\"574\" width=\"181\" height=\"68\" rx=\"14\" fill=\"rgba(12,15,21,.94)\" stroke=\"#2e3443\"/>\n          <g transform=\"translate(206 590)\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 0L2 12H9L7 24L16 10H9Z\"/></g>\n          <text x=\"236\" y=\"596\" class=\"cap\" style=\"font-size:9.5px\">VERMOGEN</text>\n          <text id=\"pwVal\" x=\"236\" y=\"620\" class=\"big-t\" style=\"font-size:22px\">0 W</text>\n          <rect x=\"236\" y=\"628\" width=\"123\" height=\"6\" rx=\"3\" fill=\"#252b37\"/><rect id=\"pwBar\" x=\"236\" y=\"628\" width=\"0\" height=\"6\" rx=\"3\" fill=\"#fbbf24\"/>\n        </g>\n        <g class=\"hit\" data-tab=\"overzicht\">\n          <rect x=\"389\" y=\"574\" width=\"181\" height=\"68\" rx=\"14\" fill=\"rgba(12,15,21,.94)\" stroke=\"#2e3443\"/>\n          <g transform=\"translate(403 590)\" fill=\"none\" stroke=\"#a78bfa\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 3a3.5 3.5 0 0 1 7 0V14a6 6 0 1 1-7 0Z\"/><path d=\"M8.5 9V16\"/></g>\n          <text x=\"433\" y=\"596\" class=\"cap\" style=\"font-size:9.5px\">BUITEN</text>\n          <text id=\"outVal\" x=\"433\" y=\"624\" class=\"big-t\" style=\"font-size:22px\">0 °C</text>\n        </g>\n\n        <!-- buffervat: altijd vol, de kleur en het warme niveau tonen hoe warm het water is -->\n        <g class=\"hit\" data-tab=\"instellingen\" data-focus=\"hyst\">\n          <text x=\"910\" y=\"258\" text-anchor=\"middle\" class=\"cap\">BUFFERVAT</text>\n          <g clip-path=\"url(#tankClip)\">\n            <rect x=\"870\" y=\"270\" width=\"80\" height=\"278\" fill=\"url(#coldGrad)\"/>\n            <g id=\"warmG\" style=\"transform:translateY(540px)\"><g id=\"waveG\"><path d=\"M850 0 q10 -7 20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 t20 0 V300 H850Z\" fill=\"url(#warmGrad)\"/></g></g>\n            <rect id=\"band\" x=\"870\" y=\"331\" width=\"80\" height=\"62\" fill=\"#fff\" opacity=\".09\"/>\n            <rect x=\"880\" y=\"286\" width=\"7\" height=\"236\" rx=\"3.5\" fill=\"#fff\" opacity=\".22\"/>\n            <g class=\"bub\" id=\"bubbles\" fill=\"#fff\" fill-opacity=\".55\"><circle cx=\"890\" cy=\"530\" r=\"3.5\" style=\"animation-delay:0s\"/><circle cx=\"910\" cy=\"540\" r=\"5\" style=\"animation-delay:1.1s;animation-duration:5.2s\"/><circle cx=\"928\" cy=\"525\" r=\"3\" style=\"animation-delay:2.2s;animation-duration:4s\"/><circle cx=\"900\" cy=\"545\" r=\"4\" style=\"animation-delay:3.1s;animation-duration:5.6s\"/><circle cx=\"920\" cy=\"535\" r=\"2.5\" style=\"animation-delay:.6s;animation-duration:3.8s\"/></g>\n          </g>\n          <rect x=\"870\" y=\"270\" width=\"80\" height=\"278\" rx=\"24\" fill=\"url(#tankShine)\"/>\n          <rect x=\"870\" y=\"270\" width=\"80\" height=\"278\" rx=\"24\" fill=\"none\" stroke=\"#c3c9d2\" stroke-width=\"2.5\"/>\n          <rect x=\"888\" y=\"260\" width=\"44\" height=\"14\" rx=\"7\" fill=\"#b9c0cb\" stroke=\"#8b939f\"/>\n          <line id=\"stMark\" x1=\"862\" x2=\"958\" y1=\"393\" y2=\"393\" stroke=\"#7dd3fc\" stroke-width=\"1.6\" stroke-dasharray=\"5 4\"/>\n          <text id=\"stMarkT\" x=\"964\" y=\"397\" class=\"tag-l\" style=\"fill:#7dd3fc\">start 36°</text>\n          <line id=\"spMark\" x1=\"862\" x2=\"958\" y1=\"331\" y2=\"331\" stroke=\"#fff\" stroke-width=\"1.6\" stroke-dasharray=\"5 4\" opacity=\".9\"/>\n          <text id=\"spMarkT\" x=\"964\" y=\"335\" class=\"tag-l\" style=\"fill:#fff\">doel 40°</text>\n          <path id=\"tankCoil\" d=\"M870,392 H902 Q912,392 912,397.5 Q912,403 902,403 H886 Q878,403 878,409 Q878,415 886,415 H870\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"3.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" opacity=\".55\"/>\n          <g fill=\"#8b939f\" stroke=\"#5d6575\"><rect x=\"860\" y=\"385\" width=\"12\" height=\"14\" rx=\"3\"/><rect x=\"860\" y=\"408\" width=\"12\" height=\"14\" rx=\"3\"/><rect x=\"860\" y=\"503\" width=\"12\" height=\"14\" rx=\"3\"/><rect x=\"948\" y=\"463\" width=\"12\" height=\"14\" rx=\"3\"/></g>\n          <text id=\"tankTemp\" x=\"910\" y=\"502\" text-anchor=\"middle\" class=\"big-t\" style=\"paint-order:stroke;font-size:26px\" stroke=\"rgba(0,0,0,.35)\" stroke-width=\"4\">36,4°</text>\n          <text x=\"910\" y=\"522\" text-anchor=\"middle\" class=\"tag-l\" style=\"fill:rgba(255,255,255,.85)\">Reg 195</text>\n        </g>\n        <!-- circulatiepomp -->\n        <g transform=\"translate(800 392)\"><circle r=\"14\" fill=\"#262b34\" stroke=\"#8b939f\" stroke-width=\"2\"/><g id=\"pumpRot\"><path d=\"M0 -9 L3.2 0 L0 9 L-3.2 0Z\" fill=\"#c3c9d2\"/><path d=\"M-9 0 L0 -3.2 L9 0 L0 3.2Z\" fill=\"#c3c9d2\" opacity=\".7\"/></g></g>\n        <!-- vloerverwarming: plat in de dekvloer -->\n        <g id=\"floorPipes\"></g>\n        <g class=\"wave\" id=\"waves\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"3\" stroke-linecap=\"round\"><path d=\"M980 540q6-8 12 0t12 0t12 0\" style=\"animation-delay:0s\"/><path d=\"M1030 540q6-8 12 0t12 0t12 0\" style=\"animation-delay:1s\"/><path d=\"M1080 540q6-8 12 0t12 0t12 0\" style=\"animation-delay:2s\"/><path d=\"M1000 540q6-8 12 0t12 0t12 0\" style=\"animation-delay:1.6s\"/></g>\n        <g id=\"waterTags\"></g>\n      </svg>\n\n      <div class=\"lamps\"><div id=\"lampRow\"></div></div>\n    </section>\n    <section class=\"m-side\">\n      <nav class=\"tabs\" id=\"tabs\" role=\"tablist\"></nav>\n      <div class=\"m-panel\" id=\"mPanel\"></div>\n    </section>\n  </div>\n</div>\n<button class=\"reopen\" id=\"reopen\" hidden><svg class=\"i\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><circle cx=\"10\" cy=\"12\" r=\"4\"/><path d=\"M17 8v8\"/></svg>Popup openen</button>\n<div class=\"toast\" id=\"toast\" role=\"status\"><svg class=\"i\" viewBox=\"0 0 24 24\"><path d=\"M5 12l5 5 9-10\"/></svg><span id=\"toastText\"></span></div>\n\n<script>\n/* =====================================================================\n   SPRSUN warmtepomp – popup voor het huisdashboard (wandtablet)\n   ---------------------------------------------------------------------\n   Plaats #modal in je huisdashboard en open hem bij een klik op de\n   warmtepomp naast het huis (openModal() / closeModal()).\n   Alles op het scherm komt uit `state`.\n   Koppelen aan Home Assistant:\n     1. Vul in ENTITIES je eigen entity_id's in (nu placeholders).\n     2. Roep bij elke hass-update `fromHass(hass)` aan  -> vult state + render().\n     3. Zet HA_BRIDGE.callService = (domain, service, data) => hass.callService(domain, service, data)\n     4. Zet SIM.active = null: dan verdwijnen de voorbeeldwaarden en gebruikt de popup alleen jouw HA-waarden.\n   Stilstand: draait de circulatiepomp niet (circ_pump en compressor uit), dan staat het water\n   stil. De aanvoersensor zakt dan terug naar kamertemperatuur; dat wordt als \"stil\" getoond en\n   alle animaties staan uit.\n   ===================================================================== */\n\nconst ENTITIES = {\n  // --- hoofdbediening & slimme aansturing (schrijfbaar) ---\n  smart_active: { id: 'input_boolean.wp_slimme_regeling_actief', type: 'bool' },\n  comfort:      { id: 'input_number.wp_comfort_verschuiving', type: 'number' },     // -5 .. +5, de 1-knops hoofdregelaar\n  sp_boiler:    { id: 'input_number.wp_setpoint_warmwater', type: 'number' },       // handmatig doel buffervat\n  // --- instellingen (popup) ---\n  curve_on:     { id: 'input_boolean.wp_slim_stooklijn_actief', type: 'bool' },\n  curve_15:     { id: 'input_number.wp_stooklijn_temp_bij_15c', type: 'number' },\n  curve_0:      { id: 'input_number.wp_stooklijn_temp_bij_0c', type: 'number' },\n  zp_on:        { id: 'input_boolean.wp_slim_zonneplan_actief', type: 'bool' },\n  boost_cheap:  { id: 'input_number.wp_slim_boost_goedkoop', type: 'number' },\n  reduce_peak:  { id: 'input_number.wp_slim_verlaging_duur', type: 'number' },\n  hyst:         { id: 'input_number.wp_hysterese_warmwater', type: 'number' },\n  slot_on:      { id: 'input_boolean.wp_slim_tijdvak_boost_actief', type: 'bool' },\n  slot_start:   { id: 'input_number.wp_slim_tijdvak_start_uur', type: 'number' },\n  slot_end:     { id: 'input_number.wp_slim_tijdvak_eind_uur', type: 'number' },\n  slot_boost:   { id: 'input_number.wp_slim_tijdvak_verhoging', type: 'number' },\n  fan_mode:     { id: 'input_select.wp_ventilatormodus_select', type: 'select' },\n  mode:         { id: 'input_select.wp_werkmodus_select', type: 'select' },\n  pump_mode:    { id: 'input_select.wp_pompmodus_select', type: 'select' },\n  // --- gedachtegang van de slimme regeling (alleen lezen) ---\n  smart_target: { id: 'sensor.wp_slimme_doeltemperatuur_berekend', type: 'number' },\n  thought:      { id: 'sensor.wp_slimme_regeling_gedachtegang', type: 'text' },\n  thought1:     { id: 'sensor.wp_slimme_regeling_gedachtegang', attr: 'stap_1_stooklijn' },\n  thought2:     { id: 'sensor.wp_slimme_regeling_gedachtegang', attr: 'stap_2_zonneplan' },\n  thought3:     { id: 'sensor.wp_slimme_regeling_gedachtegang', attr: 'stap_3_tijdvak' },\n  // --- installatie (alleen lezen) ---\n  status:       { id: 'sensor.wp_status_samenvatting', type: 'text' },\n  compressor:   { id: 'binary_sensor.wp_compressor_actief', type: 'bool' },\n  t_boiler:     { id: 'sensor.wp_boiler_temperatuur', type: 'number' },             // buffervat, Reg 195\n  sp_boiler_reg:{ id: 'sensor.wp_setpoint_warmwatervat', type: 'number' },          // doel dat de warmtepomp nu gebruikt\n  hyst_reg:     { id: 'sensor.wp_hysterese_warmwater_start_delta_t', type: 'number' },\n  t_outdoor:    { id: 'sensor.wp_buitentemperatuur', type: 'number' },\n  t_supply:     { id: 'sensor.wp_aanvoertemperatuur', type: 'number' },\n  t_return:     { id: 'sensor.wp_retourtemperatuur', type: 'number' },\n  dt_water:     { id: 'sensor.wp_water_delta_t_aanvoer_retour', type: 'number' },\n  comp_hz:      { id: 'sensor.wp_compressor_frequentie', type: 'number' },\n  comp_current: { id: 'sensor.wp_compressor_stroom', type: 'number' },\n  fan1_rpm:     { id: 'sensor.wp_ventilator_1_toerental', type: 'number' },\n  fan2_rpm:     { id: 'sensor.wp_ventilator_2_toerental', type: 'number' },\n  pump_drive:   { id: 'sensor.wp_circulatiepomp_aansturing', type: 'number' },\n  circ_pump:    { id: 'binary_sensor.wp_circulatiepomp_actief', type: 'bool' },\n  defrost:      { id: 'binary_sensor.wp_ontdooicyclus_defrost', type: 'bool' },\n  t_discharge:  { id: 'sensor.wp_persgastemperatuur', type: 'number' },\n  t_suction:    { id: 'sensor.wp_zuiggastemperatuur', type: 'number' },\n  t_condenser:  { id: 'sensor.wp_condensor_spoeltemperatuur', type: 'number' },\n  p_high:       { id: 'sensor.wp_persdruk_hogedruk', type: 'number' },\n  p_low:        { id: 'sensor.wp_zuigdruk_lagedruk', type: 'number' },\n  eev:          { id: 'sensor.wp_expansieventiel_eev_opening', type: 'number' },\n  superheat:    { id: 'sensor.wp_oververhitting_superheat', type: 'number' },\n  // --- energie, Zonneplan & thuisbatterij (alleen lezen) ---\n  power_w:      { id: 'sensor.kwh_meter_3_phase_power', type: 'number' },\n  price:        { id: 'sensor.zonneplan_current_electricity_tariff', type: 'number' },\n  forecast:     { id: 'sensor.zonneplan_current_electricity_tariff', attr: 'forecast', type: 'forecast' }, // uurtarieven\n  zp_tip:       { id: 'sensor.zonneplan_status_tip', type: 'text' },\n  batt_pct:     { id: 'sensor.thuisbatterij_percentage', type: 'number' },\n  batt_w:       { id: 'sensor.kwh_meter_3_phase_thuisbatterij_35_kw_vermogen', type: 'number' },\n  batt_status:  { id: 'sensor.thuisbatterij_batterijstatus', type: 'text' },\n  boiler_w:     { id: 'sensor.energy_socket_power', type: 'number' },               // losse tapwaterboiler\n  // --- virtuele vloer-flow (afgeleid van het afkoelen van het vat, zie HA package) ---\n  cool_rate:    { id: 'sensor.wp_buffervat_afkoelsnelheid', type: 'number' },        // °C/uur dat het vat daalt (positief = koelt af)\n  floor_demand: { id: 'binary_sensor.wp_vloerverwarming_vraagt_warmte', type: 'bool' }, // aan = vloer neemt warmte af\n};\nconst HA_BRIDGE = { callService: (d, s, data) => { if (window.parent && window.parent !== window) window.parent.postMessage({ type: \"ha-call-service\", domain: d, service: s, data: data }, \"*\"); } }; // (domain, service, data) => Promise\n\n// Opties van de select-entities; maak ze exact gelijk aan de opties in HA.\nconst OPTIONS = {\n  mode: [\n    { v: 'Warmwater (Boiler)', icon: 'tank' },\n    { v: 'Verwarmen', icon: 'floor' },\n    { v: 'Koelen', icon: 'snow' },\n  ],\n  fan_mode: ['Dagmodus (Normaal)', 'Nachtmodus (Stil)', 'Eco Modus', 'Drukregeling'],\n  pump_mode: ['Continu (Normaal)', 'Op Aanvraag (Demand)', 'Interval'],\n};\n\n// Mock-waarden (alleen voor het ontwerp)\nconst state = {\n  power: true,\n  smart_active: true, comfort: 0.5, sp_boiler: 40.5, smart_target: 40.5,\n  curve_on: true, curve_15: 38, curve_0: 46, zp_on: true, boost_cheap: 3, reduce_peak: -2,\n  hyst: 5, slot_on: false, slot_start: 12, slot_end: 15, slot_boost: 2,\n  fan_mode: 'Dagmodus (Normaal)', mode: 'Warmwater (Boiler)', pump_mode: 'Op Aanvraag (Demand)',\n  thought: 'Normaal tarief: doel 40,5 °C',\n  thought1: 'Buiten 11,4 °C → stooklijn 40,0 °C, comfort +0,5 °C = 40,5 °C',\n  thought2: 'Avondpiek 17–21u (4 uur) · batterij 64 % → de 3 duurste uren worden verlaagd. Goedkoopste uren: 02–04u en 12–14u.',\n  thought3: 'Normaal 40,5 °C · Middag-buffer 45,0 °C · Avondpiek 38,5 °C',\n  status: 'Rust - Buffervat op temperatuur',\n  compressor: false, circ_pump: false, defrost: false,\n  t_boiler: 40.3, sp_boiler_reg: 40.5, hyst_reg: 5, t_outdoor: 11.4, t_supply: 17.4, t_return: 21.4, dt_water: -4.0,\n  comp_hz: 0, comp_current: 0, fan1_rpm: 0, fan2_rpm: 0, pump_drive: 0,\n  t_discharge: 19.7, t_suction: 14.8, t_condenser: 10.9, p_high: 10.1, p_low: 10.0, eev: 0, superheat: 4.4,\n  power_w: 7, boiler_w: 2, cool_rate: 0.4, floor_demand: false,\n  price: 0.214, zp_tip: 'Laden bij lage prijs, ontladen in de avondpiek',\n  batt_pct: 64, batt_w: 0, batt_status: 'Stand-by',\n  forecast: null, // [{ h: uur 0-23, p: prijs }]\n};\nstate.forecast = [.19,.18,.17,.17,.18,.2,.24,.29,.27,.22,.17,.13,.11,.1,.11,.14,.21,.3,.36,.38,.35,.31,.26,.22].map((p, h) => ({ h, p }));\n\n/* ---------------- Simulatie (alleen voor het ontwerp) ---------------- */\nconst BASE = { ...state };\nconst HEATING = { compressor: true, circ_pump: true, defrost: false, comp_hz: 70, comp_current: 6.8, fan1_rpm: 640, fan2_rpm: 620, pump_drive: 70,\n  t_supply: 47.2, t_return: 41.8, dt_water: 5.4, t_discharge: 78.4, t_suction: 5.1, t_condenser: 44.9, p_high: 25.4, p_low: 7.9, eev: 220, superheat: 4.9 };\nconst SCENARIOS = {\n  rest:      { label: 'Rust', sub: 'Vat op temperatuur, water staat stil', patch: {} },\n  verwarmen: { label: 'Vat opwarmen', sub: 'Onder de startlijn, warmtepomp bijverwarmen tot het doel', patch: { ...HEATING,\n    status: 'Verwarmen in bedrijf (70 Hz · 3900 W)', t_boiler: 34.6, power_w: 3900, floor_demand: true } },\n  boost:     { label: 'Goedkoop uur', sub: 'Middag-buffer: doel +4,5 °C', patch: { ...HEATING, comp_hz: 64, comp_current: 6.2,\n    status: 'Verwarmen in bedrijf (64 Hz · 3500 W)', t_boiler: 40.1, sp_boiler_reg: 45, smart_target: 45, power_w: 3500, floor_demand: true, price: 0.092, batt_pct: 71, batt_w: 3200, batt_status: 'Laden',\n    thought: 'Goedkoop tarief: doel +4,5 °C → 45,0 °C',\n    thought2: 'Nu 13:00 is een van de 3 goedkoopste middaguren (+4,5 °C), de avondpiek duurt 4 uur.' } },\n  piek:      { label: 'Avondpiek', sub: 'Doel verlaagd, batterij levert', patch: {\n    status: 'Rust - Avondpiek, doel verlaagd', cool_rate: 2.3, floor_demand: true, sp_boiler_reg: 38.5, smart_target: 38.5, t_boiler: 39.6, price: 0.362, batt_pct: 58, batt_w: -4100, batt_status: 'Ontladen',\n    thought: 'Dure avondpiek: doel −2,0 °C → 38,5 °C',\n    thought2: 'Piek 17–21u · batterij 58 % → de 3 duurste uren (18–21u) worden verlaagd.' } },\n  vloer:     { label: 'Vloer vraagt warmte', sub: 'Pomp stil, vat koelt snel af', patch: { cool_rate: 2.1, floor_demand: true, t_boiler: 38.4, status: 'Rust - Vloerverwarming haalt warmte uit het vat' } },\n  defrost:   { label: 'Ontdooicyclus', sub: 'IJs van de verdamper', patch: {\n    status: 'Ontdooien - verdamper vrijmaken', compressor: true, circ_pump: true, defrost: true, comp_hz: 52, comp_current: 6.1, fan1_rpm: 0, fan2_rpm: 0, pump_drive: 70,\n    t_supply: 24.6, t_return: 28.3, dt_water: -3.7, t_boiler: 38.2, t_outdoor: 1.8, power_w: 2400,\n    t_discharge: 64.0, t_suction: -4.2, t_condenser: 12.5, p_high: 18.2, p_low: 4.9, eev: 300, superheat: 2.1 } },\n};\nconst SIM = { active: 'verwarmen' };\nlet userSettings = {};\nfunction applyScenario(key) {\n  SIM.active = key;\n  if (key) Object.assign(state, BASE, SCENARIOS[key].patch, userSettings);\n  render();\n}\n\n/* ---------------- Home Assistant koppeling ---------------- */\nfunction fromHass(hass) {\n  for (const [key, ent] of Object.entries(ENTITIES)) {\n    const s = hass.states[ent.id];\n    if (!s) continue;\n    if (ent.attr) { const v = s.attributes && s.attributes[ent.attr]; if (v == null) continue;\n      // Zonneplan-forecast: pas de veldnamen aan op wat jouw sensor teruggeeft (datetime + tarief).\n      state[key] = ent.type === 'forecast' ? v.map(x => ({ h: new Date(x.datetime).getHours(), p: Number(x.electricity_price ?? x.tariff ?? x.price) })) : v; continue; }\n    state[key] = ent.type === 'bool' ? s.state === 'on' : ent.type === 'number' ? parseFloat(s.state) : s.state;\n  }\n  render();\n}\nfunction sendToHA(key, value) {\n  const ent = ENTITIES[key];\n  if (!ent) return;\n  const [domain] = ent.id.split('.');\n  let service, data = { entity_id: ent.id };\n  if (domain === 'number' || domain === 'input_number') { service = 'set_value'; data.value = value; }\n  else if (domain === 'select' || domain === 'input_select') { service = 'select_option'; data.option = value; }\n  else if (domain === 'switch' || domain === 'input_boolean') { service = value ? 'turn_on' : 'turn_off'; }\n  else return;\n  if (HA_BRIDGE.callService) HA_BRIDGE.callService(domain, service, data);\n  else console.info('[HA]', domain + '.' + service, data);\n}\n\n/* ---------------- helpers ---------------- */\nconst $ = (s, r = document) => r.querySelector(s);\nconst $$ = (s, r = document) => [...r.querySelectorAll(s)];\nconst NS = 'http://www.w3.org/2000/svg';\nfunction svgEl(tag, attrs = {}, parent) { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; }\nconst fmt = (n, d = 1) => (n == null || isNaN(n)) ? '–' : Number(n).toLocaleString('nl-NL', { minimumFractionDigits: d, maximumFractionDigits: d });\nconst clamp = (v, a, b) => Math.min(b, Math.max(a, v));\nconst RM = matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst TSTOPS = [[8,[59,130,246]],[18,[34,195,230]],[27,[52,211,153]],[35,[250,204,21]],[45,[251,146,60]],[55,[239,68,68]]];\nfunction tempRGB(t) {\n  if (t <= TSTOPS[0][0]) return TSTOPS[0][1];\n  for (let i = 1; i < TSTOPS.length; i++) {\n    const [t1, c1] = TSTOPS[i];\n    if (t <= t1) { const [t0, c0] = TSTOPS[i - 1]; const f = (t - t0) / (t1 - t0); return c0.map((v, j) => Math.round(v + (c1[j] - v) * f)); }\n  }\n  return TSTOPS[TSTOPS.length - 1][1];\n}\nconst tempColor = (t, a = 1) => { const c = tempRGB(t); return `rgba(${c[0]},${c[1]},${c[2]},${a})`; };\nconst ICONS = {\n  bolt: '<path d=\"M13 3L5 13h6l-1 8 8-10h-6z\"/>',\n  battery: '<rect x=\"3\" y=\"8\" width=\"16\" height=\"9\" rx=\"2\"/><path d=\"M21 11v3M7 12h4\"/>',\n  tank: '<rect x=\"7\" y=\"3\" width=\"10\" height=\"18\" rx=\"4\"/><path d=\"M7 12h10\"/>',\n  floor: '<path d=\"M3 20h18\"/><path d=\"M6 16c0-2 2-2 2-4s-2-2-2-4M12 16c0-2 2-2 2-4s-2-2-2-4M18 16c0-2 2-2 2-4s-2-2-2-4\"/>',\n  snow: '<path d=\"M12 3v18M4.2 7.5l15.6 9M4.2 16.5l15.6-9\"/>',\n  combo: '<rect x=\"3\" y=\"4\" width=\"7\" height=\"16\" rx=\"3\"/><path d=\"M14 20h7M15 16c0-2 2-2 2-4s-2-2-2-4M19 16c0-2 2-2 2-4\"/>',\n  clock: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/>',\n  thermo: '<path d=\"M10 4a2 2 0 0 1 4 0v10a4 4 0 1 1-4 0z\"/><path d=\"M12 9v7\"/>',\n  sliders: '<path d=\"M4 7h10M18 7h2M4 17h4M12 17h8\"/><circle cx=\"16\" cy=\"7\" r=\"2\"/><circle cx=\"10\" cy=\"17\" r=\"2\"/>',\n  calendar: '<rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 10h16M9 3v4M15 3v4\"/>',\n  heater: '<path d=\"M6 20V9a2 2 0 0 1 4 0v11M14 20V9a2 2 0 0 1 4 0v11M4 20h16\"/>',\n  delta: '<path d=\"M12 4l8 15H4z\"/>',\n  list: '<path d=\"M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01\"/>',\n  grid: '<rect x=\"4\" y=\"4\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"13\" y=\"4\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"4\" y=\"13\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"13\" y=\"13\" width=\"7\" height=\"7\" rx=\"1.5\"/>',\n};\nconst ico = (n) => `<svg class=\"i\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">${ICONS[n] || ''}</svg>`;\n\nfunction hpState() {\n  const s = state;\n  if (s.defrost) return { key: 'defrost', label: 'Ontdooien' };\n  if (s.compressor) return { key: 'heat', label: 'Verwarmt vat' };\n  return { key: 'standby', label: 'Rust' };\n}\n// De kleppen van de vloerverwarming zitten niet in HA. Daarom meten we het via het afkoelen van het vat:\n// staat de warmtepomp stil en koelt het vat sneller af dan het normale verval (1,5 °C/u aan, onder 1,0 °C/u uit),\n// dan neemt de vloer warmte af. Eerst de virtuele binary_sensor uit HA, anders berekend uit cool_rate.\nlet floorMem = false;\nfunction floorDemand() {\n  const s = state;\n  if (typeof s.floor_demand === 'boolean' && ENTITIES.floor_demand) return s.floor_demand;\n  if (s.compressor || s.circ_pump) return floorMem;\n  if (s.cool_rate >= 1.5) floorMem = true; else if (s.cool_rate <= 1.0) floorMem = false;\n  return floorMem;\n}\n// Wat beweegt er? hp: water door de condensor naar het buffervat, floor: water door de vloer,\n// ref: koudemiddel. Staat alles stil (rust), dan is alles 0 en staan alle animaties uit.\nfunction flows() {\n  const s = state;\n  const hp = (s.circ_pump || s.compressor) ? Math.max(s.pump_drive || 0, 35) / 100 : 0;\n  const ref = s.compressor ? clamp(s.comp_hz / 60, .3, 1.4) : 0;\n  return { hp, floor: floorDemand() ? .7 : 0, ref };\n}\n// Kleur van het vat: koud = blauw, op doel = donker rood\nfunction tankColor(t, l = 0) {\n  const sp = state.sp_boiler_reg, hy = state.hyst_reg ?? state.hyst;\n  // koud = blauw, rond de startlijn oranje, op doel donkerrood\n  const st = [[sp - hy - 7, 215], [sp - hy - 4, 160], [sp - hy - 1.5, 60], [sp - hy, 32], [sp, 2]];\n  const tc = clamp(t, st[0][0], sp);\n  let h = 2;\n  for (let i = 1; i < st.length; i++) if (tc <= st[i][0]) { const [t0, h0] = st[i - 1], [t1, h1] = st[i]; h = h0 + (h1 - h0) * (tc - t0) / (t1 - t0); break; }\n  const f = clamp((t - (sp - hy - 7)) / (hy + 7), 0, 1);\n  return `hsl(${h.toFixed(0)} 78% ${(54 - 12 * f + l).toFixed(0)}%)`;\n}\n\n/* ---------------- schema opbouw ---------------- */\nconst pipes = {};\nfunction makePipe(parent, name, d, w = 6) {\n  const g = svgEl('g', {}, parent);\n  svgEl('path', { d, fill: 'none', stroke: '#07090c', 'stroke-width': w + 5, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, g);\n  const core = svgEl('path', { d, fill: 'none', stroke: '#888', 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' }, g);\n  svgEl('path', { d, fill: 'none', stroke: '#fff', 'stroke-opacity': .28, 'stroke-width': Math.max(1.4, w * .26), 'stroke-linecap': 'round', 'stroke-linejoin': 'round', transform: `translate(${-w * .14} ${-w * .14})` }, g);\n  const flow = svgEl('path', { d, fill: 'none', stroke: '#fff', 'stroke-width': Math.max(2.4, w * .55), 'stroke-linecap': 'round', 'stroke-dasharray': '0.1 14', opacity: 0 }, g);\n  pipes[name] = { core, flow, offset: 0 };\n}\n// koudemiddel (in de verkleinde unit): compressor → condensor → expansieventiel → verdamper → compressor\nconst REF = $('#refPipes');\nmakePipe(REF, 'discharge', 'M624,432 V330', 7);\nmakePipe(REF, 'liquid', 'M584,300 H500 V366', 7);\nmakePipe(REF, 'expansion', 'M488,380 H324', 7);\nmakePipe(REF, 'suction', 'M324,508 H584', 7);\n// water: unit → pomp → buffervat, en buffervat → vloer → buffervat\nconst WATER = $('#waterPipes');\nmakePipe(WATER, 'hpSup', 'M570,392 H786 M814,392 H862', 8);\nmakePipe(WATER, 'hpRet', 'M862,415 H570', 8);\nconst FLOOR_X = [834, 878, 922, 966, 1010, 1054, 1112];\nconst floorSegs = [];\nconst NOFLOW = { setAttribute() {}, style: {} };\n(function buildFloor() {\n  // één doorlopende leiding: vat → vloer → vat, met één donkere rand eronder zodat er geen naden zijn\n  const g = svgEl('g', {}, $('#floorPipes'));\n  const sup = 'M862,510 H834 Q826,510 826,518 V573 Q826,581 834,581';\n  const ret = 'M1112,581 Q1120,581 1120,573 V478 Q1120,470 1112,470 H958';\n  const all = 'M862,510 H834 Q826,510 826,518 V573 Q826,581 834,581 H1112 Q1120,581 1120,573 V478 Q1120,470 1112,470 H958';\n  const st = { fill: 'none', 'stroke-linecap': 'round', 'stroke-linejoin': 'round' };\n  svgEl('path', { d: all, ...st, stroke: '#07090c', 'stroke-width': 12 }, g);\n  const flSup = svgEl('path', { d: sup, ...st, stroke: '#888', 'stroke-width': 7 }, g);\n  for (let i = 0; i < FLOOR_X.length - 1; i++) floorSegs.push(svgEl('path', { d: `M${FLOOR_X[i]},581 H${FLOOR_X[i + 1]}`, ...st, stroke: '#888', 'stroke-width': 7 }, g));\n  const flRet = svgEl('path', { d: ret, ...st, stroke: '#888', 'stroke-width': 7 }, g);\n  svgEl('path', { d: all, ...st, stroke: '#fff', 'stroke-opacity': .25, 'stroke-width': 1.8, transform: 'translate(-1 -1.4)' }, g);\n  FLOOR_X.slice(1, -1).forEach(x => svgEl('rect', { x: x - 4, y: 573, width: 8, height: 16, rx: 3, fill: '#3a404c', stroke: '#6b7485' }, g));\n  const flow = svgEl('path', { d: all, ...st, stroke: '#fff', 'stroke-width': 3.6, 'stroke-dasharray': '0.1 14', opacity: 0 }, g);\n  pipes.flSup = { core: flSup, flow: NOFLOW, offset: 0 };\n  pipes.flRet = { core: flRet, flow: NOFLOW, offset: 0 };\n  pipes.floor = { core: null, flow, offset: 0 };\n})();\n\n// waardelabels bij de leidingen en de vloer\nconst tags = {};\nfunction makeTag(parent, name, x, y, w, label, tab) {\n  const g = svgEl('g', { class: 'hit', 'data-tab': tab }, parent);\n  g.setAttribute('transform', `translate(${x} ${y})`);\n  svgEl('rect', { width: w, height: 52, rx: 16, fill: 'rgba(22,28,41,.95)', stroke: '#3a4458', 'stroke-width': 1.5 }, g);\n  const ring = svgEl('circle', { cx: 16, cy: 19, r: 8, fill: '#5d6575', opacity: .22 }, g);\n  const dot = svgEl('circle', { cx: 16, cy: 19, r: 4.5, fill: '#5d6575' }, g);\n  const lab = svgEl('text', { x: 30, y: 23, class: 'tag-l' }, g); lab.textContent = label;\n  const v = svgEl('text', { x: 13, y: 42, class: 'tag-v' }, g);\n  tags[name] = { v, dot, ring, lab };\n}\nconst WT = $('#waterTags');\nmakeTag(WT, 'sup', 592, 322, 140, 'Aanvoer', 'overzicht');\nmakeTag(WT, 'ret', 592, 433, 140, 'Retour', 'overzicht');\nmakeTag(WT, 'floor', 1012, 400, 140, 'Vloerverwarming', 'overzicht');\n\n// meetpunten van de unit: één overzicht boven de unit en genummerde speldjes op de onderdelen\nconst UX = (x) => 185 + .55 * x, UY = (y) => 247 + .55 * y;\nconst CELLS = [\n  ['fan', 'Ventilator', '#a9cce6', 174, 380],\n  ['suction', 'Zuiggas · lagedruk', '#60a5fa', 450, 508],\n  ['eev', 'EEV · oververhitting', '#a78bfa', 500, 380],\n  ['cond', 'Condensor spoel', '#f59e0b', 624, 285],\n  ['discharge', 'Persgas · hogedruk', '#ef4444', 624, 381],\n  ['comp', 'Compressor', '#4ade80', 624, 472],\n];\n(function buildPanelCells() {\n  const P = $('#refPanel'), PIN = $('#pins');\n  svgEl('rect', { width: 520, height: 112, rx: 20, fill: 'rgba(22,28,41,.95)', stroke: '#3a4458', 'stroke-width': 1.5 }, P);\n  CELLS.forEach(([name, label, color, px, py], i) => {\n    const g = svgEl('g', { transform: `translate(${10 + (i % 3) * 170} ${10 + Math.floor(i / 3) * 50})` }, P);\n    const dot = svgEl('circle', { cx: 15, cy: 20, r: 11, fill: color }, g);\n    const n = svgEl('text', { x: 15, y: 24.5, 'text-anchor': 'middle', style: 'font:700 12px var(--f-ui);fill:#0c0f15' }, g); n.textContent = i + 1;\n    const lab = svgEl('text', { x: 36, y: 17, class: 'tag-l' }, g); lab.textContent = label;\n    const v = svgEl('text', { x: 36, y: 37, class: 'tag-v' }, g);\n    tags[name] = { v, dot, ring: null, lab };\n    const pg = svgEl('g', { transform: `translate(${UX(px)} ${UY(py)})` }, PIN);\n    svgEl('circle', { r: 10, fill: color, stroke: '#0c0f15', 'stroke-width': 2 }, pg);\n    const pn = svgEl('text', { y: 4, 'text-anchor': 'middle', style: 'font:700 11px var(--f-ui);fill:#0c0f15' }, pg); pn.textContent = i + 1;\n  });\n})();\n\n/* ---------------- render ---------------- */\nfunction setPipe(name, color, active) {\n  const p = pipes[name];\n  if (p.core) { p.core.setAttribute('stroke', color); p.core.setAttribute('opacity', active ? 1 : .5); }\n  p.flow.setAttribute('opacity', active ? .75 : 0);\n}\nfunction setTag(name, value, color, label) {\n  const t = tags[name];\n  t.v.textContent = value; t.dot.setAttribute('fill', color || '#5d6575');\n  if (t.ring) t.ring.setAttribute('fill', color || '#5d6575');\n  if (label !== undefined) t.lab.textContent = label;\n}\n\nlet lampCache = '';\nconst f0 = (v) => fmt(v, v % 1 ? 1 : 0);\nfunction renderSchema() {\n  const s = state, f = flows();\n  const sup = s.t_supply, ret = s.t_return, supC = tankColor(sup), retC = tankColor(ret);\n  const on = f.ref > 0, flowing = f.hp > 0;\n  setPipe('discharge', s.defrost ? '#fca5a5' : '#ef4444', on);\n  setPipe('liquid', '#f59e0b', on);\n  setPipe('expansion', '#38bdf8', on);\n  setPipe('suction', '#60a5fa', on);\n  setPipe('hpSup', supC, flowing);\n  setPipe('hpRet', retC, flowing);\n  // vloerwater komt uit het vat en komt zo'n 5 °C koeler terug\n  const fSup = s.t_boiler, fRet = s.t_boiler - 5, fSupC = tankColor(fSup), fRetC = tankColor(fRet);\n  setPipe('flSup', f.floor ? fSupC : '#3b6b82', f.floor > 0);\n  setPipe('flRet', f.floor ? fRetC : '#3b6b82', f.floor > 0);\n  floorSegs.forEach((p, i) => {\n    p.setAttribute('stroke', f.floor ? tankColor(fSup + (fRet - fSup) * i / (floorSegs.length - 1)) : '#3b6b82');\n    p.setAttribute('opacity', f.floor ? 1 : .5);\n  });\n  pipes.floor.flow.setAttribute('opacity', f.floor ? .55 : 0);\n  $('#floorGlowStop').setAttribute('stop-color', fSupC);\n  $('#floorGlow').setAttribute('opacity', f.floor ? 1 : 0);\n  // buffervat: altijd vol; het warme niveau stijgt naar het doel, een tweede lijn toont wanneer hij weer bijverwarmt\n  const sp = s.sp_boiler_reg, hy = s.hyst_reg ?? s.hyst, lo = sp - hy - 12, hi = sp + 4;\n  const Y = (t) => 540 - clamp((t - lo) / (hi - lo), 0, 1) * 258;\n  const yT = Y(sp), yS = Y(sp - hy);\n  $('#warmG').style.transform = `translateY(${Y(s.t_boiler).toFixed(1)}px)`;\n  $('#waveG').style.animationPlayState = flowing ? 'running' : 'paused';\n  $('#tankTop').setAttribute('stop-color', tankColor(s.t_boiler));\n  $('#tankBot').setAttribute('stop-color', tankColor(s.t_boiler - 3, -6));\n  $('#tankTemp').textContent = fmt(s.t_boiler) + '°';\n  $('#spMark').setAttribute('y1', yT); $('#spMark').setAttribute('y2', yT);\n  $('#spMarkT').setAttribute('y', yT + 4); $('#spMarkT').textContent = `doel ${f0(sp)}°`;\n  $('#stMark').setAttribute('y1', yS); $('#stMark').setAttribute('y2', yS);\n  $('#stMarkT').setAttribute('y', yS + 4); $('#stMarkT').textContent = `start ${f0(sp - hy)}°`;\n  $('#band').setAttribute('y', yT); $('#band').setAttribute('height', Math.max(0, yS - yT));\n  $('#bubbles').setAttribute('display', flowing && !RM ? 'inline' : 'none');\n  $('#waves').setAttribute('display', f.floor && !RM ? 'inline' : 'none'); $('#waves').setAttribute('stroke', fSupC);\n  $('#tankCoil').setAttribute('stroke', supC); $('#tankCoil').setAttribute('opacity', flowing ? .75 : .3);\n  // unit\n  $('#compLed').setAttribute('fill', s.compressor ? '#4ade80' : '#5d6575');\n  $('#frostFins').setAttribute('opacity', s.defrost ? .3 : 0);\n  $('#frostFan').setAttribute('opacity', s.defrost ? .2 : 0);\n  setTag('fan', `${s.fan1_rpm} RPM`, '#a9cce6');\n  setTag('suction', `${fmt(s.t_suction)}° · ${fmt(s.p_low)} bar`, '#60a5fa');\n  setTag('eev', `${s.eev} st · ${fmt(s.superheat)} K`, '#a78bfa');\n  setTag('cond', `${fmt(s.t_condenser)} °C`, '#f59e0b');\n  setTag('discharge', `${fmt(s.t_discharge)}° · ${fmt(s.p_high)} bar`, '#ef4444');\n  setTag('comp', `${fmt(s.comp_hz, 0)} Hz · ${fmt(s.comp_current)} A`, '#4ade80');\n  // water: staat het water stil, dan is dat een sensorwaarde die terugzakt, geen terugstroming\n  const dT = sup - ret;\n  setTag('sup', `${fmt(sup)} °C`, flowing ? supC : '#5d6575', flowing ? 'Aanvoer · 189' : 'Aanvoer · stil');\n  setTag('ret', `${fmt(ret)} °C`, flowing ? retC : '#5d6575', flowing ? 'Retour · 188' : 'Retour · stil');\n  setTag('floor', f.floor ? 'vraagt warmte' : 'In rust', f.floor ? fSupC : '#5d6575', f.floor ? `Vloer · ${fmt(s.cool_rate)} °/u` : 'Vloerverwarming');\n  $('#pwVal').textContent = `${s.power_w.toLocaleString('nl-NL')} W`;\n  $('#pwBar').setAttribute('width', 123 * clamp(s.power_w / 5000, 0, 1));\n  $('#outVal').textContent = `${fmt(s.t_outdoor)} °C`;\n  const L = [['floor_on', 'Vloer vraagt warmte'], ['compressor', 'Compressor'], ['circ_pump', 'Circulatiepomp' + (s.circ_pump ? ` · ${fmt(s.pump_drive, 0)}%` : '')], ['defrost', 'Ontdooien']];\n  s.floor_on = floorDemand();\n  const lampHTML = L.map(([k, l]) => `<span class=\"lamp ${s[k] ? 'on' : ''} ${k === 'defrost' ? 'ice' : ''}\"><i></i>${l}</span>`).join('')\n    + `<span class=\"lamp status\">${s.status}</span>`;\n  if (lampHTML !== lampCache) { lampCache = lampHTML; $('#lampRow').innerHTML = lampHTML; }\n}\n\nfunction renderHead() {\n  const s = state, hs = hpState();\n  $('#mBadge').textContent = hs.label; $('#mBadge').className = 'badge ' + hs.key;\n  $('#mSub').textContent = `SPRSUN · Carel · ${s.smart_active ? 'slimme regeling aan' : 'handmatig doel'}`;\n}\n\n/* ---------------- tabbladen ---------------- */\nconst TABS = [\n  { id: 'overzicht', label: 'Overzicht', icon: 'grid' },\n  { id: 'energie', label: 'Energie', icon: 'bolt' },\n  { id: 'instellingen', label: 'Instellingen', icon: 'sliders' },\n  { id: 'waarden', label: 'Waarden', icon: 'list' },\n];\nlet currentTab = 'overzicht', thOpen = false;\nconst STEP = {\n  comfort: { label: 'Comfort-verschuiving', sub: 'Te koud of te warm? Eén knop: stooklijn, boosts en verlagingen schuiven mee', icon: 'thermo', min: -5, max: 5, step: .5, signed: true },\n  sp_boiler: { label: 'Doel buffervat (handmatig)', sub: 'Alleen te kiezen als de slimme regeling uit staat', icon: 'tank', min: 25, max: 55, step: .5 },\n  hyst: { label: 'Inschakelverschil (Delta T)', sub: 'Zakt het vat zoveel onder het doel, dan gaat de warmtepomp weer bijverwarmen', icon: 'delta', min: 1, max: 10, step: .5 },\n  curve_15: { label: 'Stooklijn bij 15 °C buiten', sub: 'Basis-doel bij zacht weer', icon: 'thermo', min: 28, max: 46, step: .5 },\n  curve_0: { label: 'Stooklijn bij 0 °C buiten', sub: 'Basis-doel bij vorst', icon: 'snow', min: 34, max: 55, step: .5 },\n  boost_cheap: { label: 'Boost goedkope uren', sub: 'Extra doel in de goedkoopste uren', icon: 'bolt', min: 0, max: 6, step: .5, signed: true },\n  reduce_peak: { label: 'Verlaging dure avondpiek', sub: 'Lager doel, zodat de batterij de piek overneemt', icon: 'battery', min: -6, max: 0, step: .5, signed: true },\n  slot_start: { label: 'Startuur', sub: 'Vast tijdvak', icon: 'clock', min: 0, max: 23, step: 1, unit: 'u', d: 0 },\n  slot_end: { label: 'Einduur', sub: 'Vast tijdvak', icon: 'clock', min: 0, max: 23, step: 1, unit: 'u', d: 0 },\n  slot_boost: { label: 'Extra verhoging in het tijdvak', sub: 'Komt bovenop het doel', icon: 'bolt', min: 0, max: 6, step: .5, signed: true },\n};\nObject.entries(STEP).forEach(([k, c]) => { c.key = k; c.unit = c.unit || '°C'; });\nconst ALL_STEPPERS = Object.values(STEP);\nconst stepperHTML = (c) => `<div class=\"row\" data-stepper=\"${c.key}\">\n    <div class=\"row-line\"><span class=\"ico\">${ico(c.icon)}</span>\n      <div class=\"row-text\"><div class=\"row-title\">${c.label}</div><div class=\"row-sub\">${c.sub}</div></div>\n      <div class=\"step-ctrl\"><button class=\"step\" data-step=\"-1\" aria-label=\"${c.label} lager\">−</button><div class=\"step-val num\"><span data-val></span><small>${c.unit}</small></div><button class=\"step\" data-step=\"1\" aria-label=\"${c.label} hoger\">+</button></div>\n    </div>\n    <input type=\"range\" id=\"rng-${c.key}\" min=\"${c.min}\" max=\"${c.max}\" step=\"${c.step}\" aria-label=\"${c.label}\">\n    <div class=\"range-ends num\"><span>${c.min}</span><span>${c.max}</span></div></div>`;\nconst segHTML = (key, opts, compact) => `<div class=\"seg ${compact ? 'compact' : ''}\" data-seg=\"${key}\">${opts.map(o => { const v = typeof o === 'string' ? o : o.v; return `<button data-val=\"${v}\" aria-pressed=\"false\">${o.icon ? ico(o.icon) : ''}<span>${v}</span></button>`; }).join('')}</div>`;\nconst switchRow = (key, title, sub, icon) => `<div class=\"row\"><div class=\"row-line\"><span class=\"ico\">${ico(icon)}</span><div class=\"row-text\"><div class=\"row-title\">${title}</div><div class=\"row-sub\">${sub}</div></div><button class=\"switch\" role=\"switch\" data-switch=\"${key}\" aria-checked=\"false\" aria-label=\"${title}\"></button></div></div>`;\n\nconst ALL_VALUES = [\n  { title: 'Slimme regeling', items: [\n    ['smart_target', 'Berekende doeltemperatuur', 'nu', '°C', 1, true], ['sp_boiler_reg', 'Doel in de warmtepomp', 'Reg 3', '°C', 1, true],\n    ['hyst_reg', 'Inschakelverschil (Delta T)', 'start onder doel', '°C', 1], ['comfort', 'Comfort-verschuiving', '', '°C', 1],\n    ['cool_rate', 'Afkoelsnelheid buffervat', 'meet de vloer-flow', '°C/u', 1]] },\n  { title: 'Temperaturen', items: [\n    ['t_boiler', 'Buffervat vloerverwarming', 'Reg 195', '°C', 1, true],\n    ['t_supply', 'Aanvoer vanuit warmtepomp', 'Reg 189', '°C', 1, true], ['t_return', 'Retour naar warmtepomp', 'Reg 188', '°C', 1, true],\n    ['delta', 'Delta T water (aanvoer − retour)', 'berekend', '°C', 1], ['t_outdoor', 'Buitentemperatuur', 'Reg 190', '°C', 1, true]] },\n  { title: 'Compressor, ventilatoren & pomp', items: [\n    ['comp_hz', 'Compressor frequentie', '', 'Hz', 1], ['comp_current', 'Compressor stroom', '', 'A', 1],\n    ['fan1_rpm', 'Ventilator 1 toerental', '', 'RPM', 0], ['fan2_rpm', 'Ventilator 2 toerental', '', 'RPM', 0], ['pump_drive', 'Circulatiepomp aansturing', '', '%', 1]] },\n  { title: 'Koelkreis', items: [\n    ['t_discharge', 'Persgastemperatuur', 'heetgas', '°C', 1], ['t_suction', 'Zuiggastemperatuur', '', '°C', 1], ['t_condenser', 'Condensor spoeltemperatuur', '', '°C', 1],\n    ['p_high', 'Persdruk / hogedruk', '', 'bar', 1], ['p_low', 'Zuigdruk / lagedruk', '', 'bar', 1], ['eev', 'Expansieventiel (EEV) opening', '', 'stappen', 0], ['superheat', 'Oververhitting', 'superheat', 'K', 1]] },\n  { title: 'Energie & thuisbatterij', items: [\n    ['power_w', 'Warmtepomp actueel vermogen', '3-fase', 'W', 0], ['boiler_w', 'Tapwaterboiler actueel vermogen', '', 'W', 0],\n    ['price', 'Zonneplan stroomprijs', '', '€/kWh', 3], ['batt_pct', 'Thuisbatterij', '35 kWh', '%', 0], ['batt_w', 'Thuisbatterij vermogen', '', 'W', 0]] },\n];\n\nconst PANELS = {\n  overzicht: () => `<div class=\"panel\">\n    <div class=\"box think\" id=\"think\">\n      <div class=\"th-top\"><span class=\"chip-s\" id=\"thChip\"></span><button class=\"th-more\" id=\"thMore\" hidden>Waarom?</button></div>\n      <div class=\"th-sum\" id=\"thSum\"></div>\n      <div class=\"th-sub\" id=\"thSub\"></div>\n      <div class=\"th-steps\" id=\"thSteps\" hidden></div>\n    </div>\n    <div class=\"tiles\" id=\"ovTiles\"></div>\n    <div class=\"sec\"><div class=\"sec-h\">Temperatuurverloop <em>24 uur</em></div><div class=\"box chart-wrap\"><div id=\"chart\"></div><div class=\"legend\" id=\"legend\"></div></div></div>\n  </div>`,\n  energie: () => `<div class=\"panel\">\n    <div class=\"box statusbox\"><span>Stroomprijs nu (Zonneplan)</span><b id=\"enPrice\"></b><span id=\"enTip\"></span></div>\n    <div class=\"sec\"><div class=\"sec-h\">Prijs per uur <em>groen goedkoop · rood duur</em></div><div class=\"box chart-wrap\"><div id=\"fc\"></div></div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Thuisbatterij <em>35 kWh</em></div><div class=\"box batt\" id=\"batt\"></div></div>\n  </div>`,\n  instellingen: () => `<div class=\"panel\">\n    <div class=\"sec\"><div class=\"sec-h\">Hoofdregeling</div><div class=\"box\">${stepperHTML(STEP.comfort)}${switchRow('smart_active', 'Slimme regeling', 'Het doel volgt stooklijn, stroomprijs en batterij', 'bolt')}</div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Doel buffervat</div><div class=\"box\">${stepperHTML(STEP.sp_boiler)}${stepperHTML(STEP.hyst)}</div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Weersafhankelijke stooklijn</div><div class=\"box\">${switchRow('curve_on', 'Stooklijn gebruiken', 'Het doel schuift mee met de buitentemperatuur', 'thermo')}${stepperHTML(STEP.curve_15)}${stepperHTML(STEP.curve_0)}</div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Zonneplan &amp; batterij</div><div class=\"box\">${switchRow('zp_on', 'Prijs- en batterij-optimalisatie', 'Goedkope uren bufferen, dure avondpiek overslaan', 'bolt')}${stepperHTML(STEP.boost_cheap)}${stepperHTML(STEP.reduce_peak)}</div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Vast tijdvak</div><div class=\"box\">${switchRow('slot_on', 'Extra tijdvak-boost', 'Vast schema bovenop de slimme regeling', 'clock')}${stepperHTML(STEP.slot_start)}${stepperHTML(STEP.slot_end)}${stepperHTML(STEP.slot_boost)}</div></div>\n    <div class=\"sec\"><div class=\"sec-h\">Werkmodus</div>${segHTML('mode', OPTIONS.mode)}</div>\n    <div class=\"sec\"><div class=\"sec-h\">Geluidsmodus buitenunit</div>${segHTML('fan_mode', OPTIONS.fan_mode, true)}</div>\n    <div class=\"sec\"><div class=\"sec-h\">Circulatiepomp modus</div>${segHTML('pump_mode', OPTIONS.pump_mode, true)}</div>\n  </div>`,\n  waarden: () => `<div class=\"panel\">${ALL_VALUES.map(g => `<div class=\"sec\"><div class=\"sec-h\">${g.title}</div><div class=\"box list\" data-group=\"${g.title}\"></div></div>`).join('')}</div>`,\n};\n\nfunction buildPanel() {\n  $('#tabs').innerHTML = TABS.map(t => `<button class=\"tab\" role=\"tab\" data-tab=\"${t.id}\" aria-selected=\"${t.id === currentTab}\">${ico(t.icon)}${t.label}</button>`).join('');\n  $('#mPanel').innerHTML = PANELS[currentTab]();\n  $('#mPanel').scrollTop = 0;\n  if (currentTab === 'overzicht') buildChart();\n  renderPanel();\n}\nfunction buildForecast() {\n  const fc = state.forecast || [], W = 520, H = 150, L = 8, B = 22, n = fc.length || 1, bw = (W - L * 2) / n;\n  const max = Math.max(...fc.map(x => x.p), .01), byP = [...fc].sort((a, b) => a.p - b.p);\n  const cheap = new Set(byP.slice(0, 3).map(x => x.h)), dear = new Set(byP.slice(-4).map(x => x.h)), nowH = new Date().getHours();\n  let g = '';\n  fc.forEach((x, i) => {\n    const h = (H - B - 14) * x.p / max, c = cheap.has(x.h) ? '#4ade80' : dear.has(x.h) ? '#f87171' : '#475569';\n    g += `<rect x=\"${L + i * bw + 2}\" y=\"${H - B - h}\" width=\"${bw - 4}\" height=\"${h}\" rx=\"3\" fill=\"${c}\" ${x.h === nowH ? 'stroke=\"#fff\" stroke-width=\"2\"' : ''}/>`;\n    if (x.h % 6 === 0) g += `<text x=\"${L + i * bw + bw / 2}\" y=\"${H - 6}\" text-anchor=\"middle\">${String(x.h).padStart(2, '0')}u</text>`;\n  });\n  $('#fc').innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Stroomprijs per uur\">${g}</svg>`;\n}\nfunction renderPanel() {\n  const s = state, body = $('#mPanel'), flowing = flows().hp > 0;\n  $$('[data-stepper]', body).forEach(row => {\n    const key = row.dataset.stepper, c = STEP[key];\n    row.querySelector('[data-val]').textContent = (c.signed && s[key] > 0 ? '+' : '') + fmt(s[key], c.d ?? 1);\n    const r = row.querySelector('input');\n    if (document.activeElement !== r) r.value = s[key];\n    r.style.setProperty('--p', ((s[key] - c.min) / (c.max - c.min) * 100) + '%');\n    if (key === 'sp_boiler') r.style.setProperty('--trk', tempColor(s[key]));\n    if (key === 'comfort') r.style.setProperty('--trk', s[key] < 0 ? '#60a5fa' : '#fb923c');\n    if (key === 'sp_boiler') row.classList.toggle('dim', !!s.smart_active);\n  });\n  $$('[data-seg]', body).forEach(seg => $$('button', seg).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.val === s[seg.dataset.seg]))));\n  $$('[data-switch]', body).forEach(b => b.setAttribute('aria-checked', String(!!s[b.dataset.switch])));\n  if ($('#think')) {\n    const hy = s.hyst_reg ?? s.hyst, on = !!s.smart_active;\n    $('#thChip').textContent = on ? 'Slimme regeling aan' : 'Slimme regeling uit'; $('#thChip').classList.toggle('on', on);\n    $('#thSum').textContent = on ? s.thought : 'Handmatig doel';\n    $('#thSub').textContent = `Doel ${fmt(s.sp_boiler_reg)} °C · bijverwarmen onder ${fmt(s.sp_boiler_reg - hy)} °C · comfort ${s.comfort > 0 ? '+' : ''}${fmt(s.comfort)} °C`;\n    $('#thMore').hidden = !on;\n    $('#thSteps').hidden = !on || !thOpen;\n    $('#thMore').textContent = thOpen ? 'Sluiten' : 'Waarom?';\n    $('#thSteps').innerHTML = [['1', 'Stooklijn', s.thought1], ['2', 'Zonneplan & batterij', s.thought2], ['3', 'Tijdvak', s.thought3]].map(([n, t, x]) => `<div class=\"th-step\"><i>${n}</i><div><b>${t}</b><span>${x}</span></div></div>`).join('');\n  }\n  if ($('#ovTiles')) {\n    const hy = s.hyst_reg ?? s.hyst;\n    const t = [\n      ['Buffervat', s.t_boiler, '°C', `start ${f0(s.sp_boiler_reg - hy)}° · doel ${f0(s.sp_boiler_reg)}°`, 'instellingen', tankColor(s.t_boiler)],\n      ['Aanvoer', s.t_supply, '°C', flowing ? 'Reg 189' : 'water staat stil', '', flowing ? tankColor(s.t_supply) : '#5d6575'],\n      ['Retour', s.t_return, '°C', flowing ? 'Reg 188' : 'water staat stil', '', flowing ? tankColor(s.t_return) : '#5d6575'],\n      ['Vermogen', s.power_w, 'W', `tapwaterboiler ${fmt(s.boiler_w, 0)} W`, 'energie', '#fbbf24', 0],\n      ['Stroomprijs', s.price, '€/kWh', 'Zonneplan', 'energie', '#4ade80', 3],\n      ['Thuisbatterij', s.batt_pct, '%', s.batt_status, 'energie', '#60a5fa', 0],\n    ];\n    $('#ovTiles').innerHTML = t.map(([l, v, u, sub, tab, c, d]) => `<button class=\"tile\" ${tab ? `data-tab=\"${tab}\"` : 'tabindex=\"-1\"'}><span><i class=\"sw\" style=\"background:${c}\"></i>${l}</span><b class=\"num\">${fmt(v, d ?? 1)}<small>${u}</small></b><em>${sub}</em></button>`).join('');\n  }\n  if ($('#enPrice')) {\n    $('#enPrice').textContent = `€ ${fmt(s.price, 3)} per kWh`; $('#enTip').textContent = s.zp_tip;\n    buildForecast();\n    const w = s.batt_w, wtxt = w > 0 ? `laden · ${w.toLocaleString('nl-NL')} W` : w < 0 ? `ontladen · ${Math.abs(w).toLocaleString('nl-NL')} W` : 'geen vermogen';\n    $('#batt').innerHTML = `<div class=\"batt-top\"><b class=\"num\">${fmt(s.batt_pct, 0)}<small>%</small></b></div>\n      <div class=\"batt-bar\"><i style=\"width:${clamp(s.batt_pct, 0, 100)}%\"></i></div><div class=\"batt-sub\"><span>${s.batt_status}</span><span>${wtxt}</span></div>`;\n  }\n  $$('[data-group]', body).forEach(box => {\n    const g = ALL_VALUES.find(x => x.title === box.dataset.group);\n    box.innerHTML = g.items.map(([k, label, sub, unit, d, isTemp]) => {\n      let v = k === 'delta' ? s.t_supply - s.t_return : s[k], txt = `${fmt(v, d)} ${unit}`, sw = isTemp ? (k === 'sp_boiler_reg' || k === 'smart_target' || k === 't_outdoor' ? tempColor(v) : tankColor(v)) : '';\n      if (!flowing && (k === 't_supply' || k === 't_return' || k === 'delta')) { sub = (k === 'delta' ? '' : sub + ' · ') + 'water staat stil'; sw = '#5d6575'; if (k === 'delta') txt = '–'; }\n      return `<div class=\"li\"><span class=\"sw\" style=\"${sw ? `background:${sw}` : ''}\"></span><div class=\"lt\">${label}${sub ? `<small>${sub}</small>` : ''}</div><b class=\"num\">${txt}</b></div>`;\n    }).join('');\n  });\n}\n\n/* 24-uurs grafiek (mock-historie; in HA te vervangen door de history-API) */\nconst SERIES = [\n  { key: 'boiler', label: 'Boiler', color: '#3b82f6', on: true },\n  { key: 'setpoint', label: 'Setpoint', color: '#fbbf24', on: true },\n  { key: 'aanvoer', label: 'Aanvoer', color: '#f87171', on: true },\n  { key: 'retour', label: 'Retour', color: '#34d399', on: true },\n  { key: 'buiten', label: 'Buiten', color: '#a78bfa', on: true },\n];\nconst HISTORY = (() => {\n  const out = { boiler: [], setpoint: [], aanvoer: [], retour: [], buiten: [] };\n  let b = 38, heating = false, sup = 22, seed = 3;\n  const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280 - .5;\n  for (let i = 0; i < 97; i++) {\n    if (b < 35.5) heating = true;\n    if (b >= 40.5) heating = false;\n    b += heating ? 1.1 : -0.22;\n    sup += ((heating ? 46 : 19) - sup) * 0.45;\n    out.boiler.push(b); out.setpoint.push(40.5);\n    out.aanvoer.push(sup + rnd()); out.retour.push(sup + (heating ? -5 : 3.5) + rnd());\n    out.buiten.push(9.5 + 2.6 * Math.sin((i / 4 - 9) / 24 * Math.PI * 2) + rnd() * .6);\n  }\n  return out;\n})();\nfunction buildChart() {\n  const W = 520, H = 220, L = 30, R = 10, T = 10, B = 26;\n  const x = (i) => L + (W - L - R) * i / 96, y = (v) => T + (H - T - B) * (1 - (v - 5) / 50);\n  const startH = (new Date().getHours() + 1) % 24;\n  let g = '';\n  for (let v = 10; v <= 50; v += 10) g += `<line x1=\"${L}\" x2=\"${W - R}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"#232834\"/><text x=\"${L - 6}\" y=\"${y(v) + 4}\" text-anchor=\"end\">${v}</text>`;\n  for (let k = 0; k <= 4; k++) { const i = k * 24; g += `<text x=\"${x(i)}\" y=\"${H - 8}\" text-anchor=\"${k === 0 ? 'start' : k === 4 ? 'end' : 'middle'}\">${k === 4 ? 'nu' : String((startH + k * 6) % 24).padStart(2, '0') + ':00'}</text>`; }\n  SERIES.forEach(s => {\n    if (!s.on) return;\n    const d = HISTORY[s.key].map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join('');\n    g += `<path d=\"${d}\" fill=\"none\" stroke=\"${s.color}\" stroke-width=\"${s.key === 'setpoint' ? 1.5 : 2}\" ${s.key === 'setpoint' ? 'stroke-dasharray=\"5 4\"' : ''} stroke-linejoin=\"round\"/><circle cx=\"${x(96)}\" cy=\"${y(HISTORY[s.key][96])}\" r=\"3.5\" fill=\"${s.color}\" stroke=\"#181c26\" stroke-width=\"2\"/>`;\n  });\n  $('#chart').innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Temperatuurverloop afgelopen 24 uur\">${g}</svg>`;\n  $('#legend').innerHTML = SERIES.map(s => `<button data-series=\"${s.key}\" aria-pressed=\"${s.on}\"><i style=\"background:${s.color}\"></i>${s.label}</button>`).join('');\n}\n\n/* ---------------- kast: voorkant weg, binnenkant zichtbaar ---------------- */\nlet hpTaps = 0, hpTapT;\nfunction hpSet(open) {\n  $('#schema').classList.toggle('open', open);\n  hpTaps = 0;\n}\nfunction hpTap() {\n  hpTaps++;\n  clearTimeout(hpTapT);\n  hpTapT = setTimeout(() => { hpTaps = 0; }, 1500);\n  if (hpTaps >= 3) hpSet(!$('#schema').classList.contains('open'));\n}\n\n/* ---------------- popup openen / sluiten ---------------- */\nfunction openModal(tab) { if (tab) currentTab = tab; $('#modal').hidden = false; $('#reopen').hidden = true; buildPanel(); hpSet(false); kick(); }\nfunction closeModal() { $('#modal').hidden = true; $('#reopen').hidden = false; if (window.parent && window.parent !== window) window.parent.postMessage({ type: 'close-heatpump-popup' }, '*'); }\n\n/* ---------------- interactie ---------------- */\nfunction setValue(key, value, send = true) {\n  state[key] = value; userSettings[key] = value;\n  if (key === 'hyst') state.hyst_reg = value;\n  if (key === 'sp_boiler' && !state.smart_active) state.sp_boiler_reg = value;\n  render();\n  if (send) sendToHA(key, value);\n}\nlet toastTimer;\nfunction toast(msg) { $('#toastText').textContent = msg; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 1800); }\n\ndocument.addEventListener('click', (e) => {\n  const t = e.target;\n  if (t.closest('#reopen')) { openModal(); return; }\n  if (t.closest('#hpFront') || t.closest('#fanGroup')) { hpTap(); return; }\n  if (t.closest('#mClose')) { closeModal(); return; }\n  const tab = t.closest('[data-tab]');\n  if (tab && tab.dataset.tab) {\n    currentTab = tab.dataset.tab; buildPanel();\n    const focus = tab.getAttribute('data-focus');\n    if (focus) { const r = $(`[data-stepper=\"${focus}\"]`); if (r) r.scrollIntoView({ block: 'center' }); }\n    return;\n  }\n  if (t.closest('#thMore')) { thOpen = !thOpen; renderPanel(); return; }\n  const segb = t.closest('[data-seg] button');\n  if (segb) { const key = segb.closest('[data-seg]').dataset.seg; setValue(key, segb.dataset.val); if (key === 'mode' && SIM.active) setTimeout(() => { state.mode_confirmed = state.mode; render(); }, 900); toast(`${segb.dataset.val} ingesteld`); return; }\n  const sw = t.closest('[data-switch]');\n  if (sw) { const k = sw.dataset.switch; setValue(k, !state[k]); toast(`${sw.getAttribute('aria-label')} ${state[k] ? 'aan' : 'uit'}`); return; }\n  const ser = t.closest('[data-series]');\n  if (ser) { const s = SERIES.find(x => x.key === ser.dataset.series); s.on = !s.on; buildChart(); return; }\n});\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });\n\n// stepper met vasthouden-om-te-herhalen\nlet holdT, holdI, pendingKey = null;\nfunction stepOnce(btn) {\n  const key = btn.closest('[data-stepper]').dataset.stepper, c = STEP[key];\n  setValue(key, clamp(Math.round((state[key] + c.step * +btn.dataset.step) / c.step) * c.step, c.min, c.max), false);\n  return key;\n}\ndocument.addEventListener('pointerdown', (e) => {\n  const btn = e.target.closest('.step'); if (!btn) return;\n  e.preventDefault();\n  pendingKey = stepOnce(btn);\n  holdT = setTimeout(() => { holdI = setInterval(() => stepOnce(btn), 110); }, 420);\n});\nfunction endHold() {\n  clearTimeout(holdT); clearInterval(holdI);\n  if (pendingKey) { const c = STEP[pendingKey]; sendToHA(pendingKey, state[pendingKey]); toast(`${c.label}: ${fmt(state[pendingKey], c.d ?? 1)} ${c.unit}`); pendingKey = null; }\n}\n['pointerup', 'pointercancel'].forEach(ev => document.addEventListener(ev, endHold));\ndocument.addEventListener('input', (e) => { const r = e.target.closest('[data-stepper] input'); if (r) setValue(r.closest('[data-stepper]').dataset.stepper, +r.value, false); });\ndocument.addEventListener('change', (e) => {\n  const r = e.target.closest('[data-stepper] input');\n  if (r) { const key = r.closest('[data-stepper]').dataset.stepper, c = STEP[key]; sendToHA(key, state[key]); toast(`${c.label}: ${fmt(state[key], c.d ?? 1)} ${c.unit}`); }\n});\n\n/* ---------------- animatie ----------------\n   Zuinig voor een wandtablet: maximaal 20 beelden per seconde, de lus stopt volledig zodra er niets\n   beweegt (stand-by) en ook als de popup dicht is of het scherm verborgen is. */\nlet fanA = 0, pumpA = 0, last = performance.now(), lastDraw = 0, rafId = 0;\nconst FRAME_MS = 1000 / 20;\nfunction animating() {\n  if (RM || document.hidden || $('#modal').hidden) return false;\n  const f = flows();\n  return f.ref > 0 || f.hp > 0 || f.floor > 0 || (state.power && !state.defrost && state.fan1_rpm > 0);\n}\nfunction kick() { if (!rafId && animating()) { last = performance.now(); rafId = requestAnimationFrame(frame); } }\nfunction frame(now) {\n  rafId = 0;\n  if (!animating()) return;\n  if (now - lastDraw >= FRAME_MS) {\n    const dt = Math.min(.1, (now - last) / 1000); last = now; lastDraw = now;\n    const s = state, f = flows();\n    // De ventilator draait ook achter het rooster van de dichte kast.\n    const spin = s.power && !s.defrost;\n    fanA += (spin ? s.fan1_rpm : 0) / 60 * 360 * dt * .16;\n    $('#fanRot').setAttribute('transform', `rotate(${(fanA % 360).toFixed(1)})`);\n    pumpA += f.hp * 720 * dt;\n    $('#pumpRot').setAttribute('transform', `rotate(${(pumpA % 360).toFixed(1)})`);\n    const move = (keys, speed) => keys.forEach(k => { pipes[k].offset -= speed * dt; pipes[k].flow.style.strokeDashoffset = pipes[k].offset; });\n    move(['discharge', 'liquid', 'expansion', 'suction'], f.ref * 50);\n    move(['hpSup', 'hpRet'], f.hp * 46);\n    move(['flSup', 'floor', 'flRet'], f.floor * 40);\n  }\n  rafId = requestAnimationFrame(frame);\n}\ndocument.addEventListener('visibilitychange', kick);\n\n/* ---------------- simulatie-ruis, wake lock ---------------- */\nsetInterval(() => {\n  if (document.hidden || $('#modal').hidden || !SIM.active || !state.compressor || !state.power) return;\n  const j = (v, a) => +(v + (Math.random() - .5) * a).toFixed(1);\n  state.comp_hz = j(state.comp_hz, 1.2);\n  state.t_supply = j(state.t_supply, .2);\n  state.t_return = j(state.t_return, .2);\n  state.t_discharge = j(state.t_discharge, .6);\n  state.power_w = Math.round(state.power_w + (Math.random() - .5) * 40);\n  if (SIM.active === 'verwarmen' || SIM.active === 'boost') {\n    // het vat loopt vol naar het doel; is het bereikt, dan gaat de warmtepomp in rust\n    state.t_boiler = +Math.min(state.sp_boiler_reg, state.t_boiler + .5).toFixed(1);\n    if (state.t_boiler >= state.sp_boiler_reg) {\n      const tb = state.t_boiler, sp = state.sp_boiler_reg;\n      Object.assign(state, BASE, SCENARIOS.rest.patch, userSettings, { t_boiler: tb, sp_boiler_reg: sp, smart_target: sp }); SIM.active = 'rest'; render(); return;\n    }\n  }\n  renderHead(); renderSchema();\n  if (currentTab !== 'instellingen') renderPanel();\n}, 2500);\n(async () => { try { if ('wakeLock' in navigator) await navigator.wakeLock.request('screen'); } catch (e) {} })();\n\nfunction render() { renderHead(); renderSchema(); renderPanel(); kick(); }\n\napplyScenario(SIM.active);\nopenModal('overzicht');\nkick();\n\nwindow.addEventListener('message', (ev) => {\n  if (ev.data && ev.data.type === 'hass-update' && ev.data.hass) {\n    fromHass(ev.data.hass);\n  }\n});\nif (window.parent && window.parent !== window) {\n  window.parent.postMessage({ type: 'heatpump-ready' }, '*');\n}\n\n</script>\n";
